/* =========================================================
   PAINTCRAFT
   PART 3 — RESPONSIVE CSS

   DESKTOP
   IPAD PRO
   IPAD MINI
   MOBILE
========================================================= */
/* =========================================================
   RESPONSIVE HEADER
   MOVE HAMBURGER TO RIGHT SIDE
========================================================= */

@media (max-width: 1199px) {

    .header-container {
        display: flex;
        align-items: center;
        justify-content: space-between;
        width: 100%;
    }

    .site-logo {
        flex: 0 0 auto;
    }

    .hamburger-button {
        display: flex;
        align-items: center;
        justify-content: center;
        flex: 0 0 auto;
        margin-left: auto;
    }

}

/* =========================================================
   01. LARGE DESKTOP
   1200px AND ABOVE
========================================================= */

@media (min-width: 1200px) {

    /* -----------------------------------------------------
       HEADER
    ----------------------------------------------------- */

    .header-container {
        min-height: 82px;

        padding-left: 30px;
        padding-right: 30px;

        gap: 22px;
    }


    /* -----------------------------------------------------
       LOGO
    ----------------------------------------------------- */

    .site-logo {
        width: 185px;
        flex: 0 0 185px;
    }

    .logo-image {
        width: 185px;
    }


    /* -----------------------------------------------------
       DESKTOP NAVIGATION
    ----------------------------------------------------- */

    .desktop-navigation {
        display: flex;
    }

    .desktop-header-actions {
        display: flex;
    }


    /* -----------------------------------------------------
       HAMBURGER
    ----------------------------------------------------- */

    .hamburger-button {
        display: none;
    }


    /* -----------------------------------------------------
       MOBILE DRAWER
    ----------------------------------------------------- */

    .mobile-navigation {
        display: none;
    }

}


/* =========================================================
   02. TABLET + MOBILE
   1199px AND BELOW

   HAMBURGER IS USED
========================================================= */

@media (max-width: 1199px) {

    /* -----------------------------------------------------
       HEADER
    ----------------------------------------------------- */

    .site-header {
        width: 100%;
    }


    .header-container {
        width: 100%;

        min-height: 76px;

        padding-left: 24px;
        padding-right: 24px;

        gap: 16px;
    }


    /* -----------------------------------------------------
       HIDE DESKTOP NAVIGATION
    ----------------------------------------------------- */

    .desktop-navigation {
        display: none !important;
    }


    /* -----------------------------------------------------
       HIDE DESKTOP ACTIONS

       RTL
       DARK MODE
       LOGIN
       QUOTE

       These MUST NOT appear outside hamburger.
    ----------------------------------------------------- */

    .desktop-header-actions {
        display: none !important;
    }


    /* -----------------------------------------------------
       SHOW HAMBURGER
    ----------------------------------------------------- */

    .hamburger-button {
        display: flex !important;

        margin-left: auto;

        flex: 0 0 46px;
    }


    /* -----------------------------------------------------
       MOBILE DRAWER
    ----------------------------------------------------- */

    .mobile-navigation {
        display: block;

        position: fixed;

        top: 0;
        right: 0;

        width: 400px;
        max-width: 90vw;

        height: 100vh;

        background-color: var(--color-bg);

        border-left: 1px solid var(--color-border);

        box-shadow:
            -10px 0 35px rgba(0, 0, 0, 0.12);

        overflow-y: auto;

        z-index: 9999;

        transform: translateX(100%);

        visibility: hidden;
        opacity: 0;

        transition:
            transform 0.3s ease,
            opacity 0.3s ease,
            visibility 0.3s ease;
    }


    /* -----------------------------------------------------
       OPEN DRAWER
    ----------------------------------------------------- */

    .mobile-navigation.active {
        transform: translateX(0);

        visibility: visible;
        opacity: 1;
    }


    /* -----------------------------------------------------
       DRAWER INNER
    ----------------------------------------------------- */

    .mobile-navigation-inner {
        width: 100%;

        min-height: 100%;

        padding: 26px;

        display: flex;
        flex-direction: column;

        box-sizing: border-box;
    }


    /* -----------------------------------------------------
       MOBILE MENU HEADER
    ----------------------------------------------------- */

    .mobile-menu-header {
        width: 100%;

        min-height: 52px;

        display: flex;
        align-items: center;
        justify-content: space-between;
    }


    /* -----------------------------------------------------
       MOBILE MENU
    ----------------------------------------------------- */

    .mobile-menu {
        width: 100%;
    }


    .mobile-nav-list {
        width: 100%;
    }


    .mobile-nav-item {
        width: 100%;
    }


    .mobile-nav-link {
        width: 100%;

        min-height: 52px;

        font-size: 16px;
    }


    .mobile-dropdown-menu {
        width: 100%;
    }


    .mobile-dropdown-menu a {
        min-height: 42px;

        font-size: 14px;
    }


    /* -----------------------------------------------------
       MOBILE HEADER ACTIONS

       THESE STAY INSIDE THE DRAWER
    ----------------------------------------------------- */

    .mobile-header-actions {
        width: 100%;

        margin-top: auto;

        padding-top: 24px;

        display: flex;
        flex-direction: column;

        gap: 10px;

        box-sizing: border-box;
    }


    .mobile-header-actions .mobile-action-btn,
    .mobile-header-actions .mobile-quote-btn {
        width: 100%;

        min-width: 100%;

        box-sizing: border-box;
    }


    /* RTL */

    .mobile-header-actions .rtl-btn,
    .mobile-header-actions .dark-mode-btn {
        width: 100%;

        min-width: 100%;

        height: 46px;
        min-height: 46px;

        display: flex;
        align-items: center;
        justify-content: center;

        padding: 0;
    }


    /* LOGIN */

    .mobile-header-actions .login-btn {
        width: 100%;

        min-height: 46px;

        display: flex;
        align-items: center;
        justify-content: center;
    }


    /* QUOTE */

    .mobile-header-actions .mobile-quote-btn {
        width: 100%;

        min-height: 46px;

        display: flex;
        align-items: center;
        justify-content: center;
    }


    /* -----------------------------------------------------
       BODY LOCK
    ----------------------------------------------------- */

    body.menu-open {
        overflow: hidden;
    }

}


/* =========================================================
   03. IPAD PRO
   769px — 1199px
========================================================= */

@media (min-width: 769px) and (max-width: 1199px) {

    /* -----------------------------------------------------
       HEADER
    ----------------------------------------------------- */

    .header-container {
        min-height: 82px;

        padding-left: 30px;
        padding-right: 30px;

        gap: 16px;
    }


    /* -----------------------------------------------------
       LOGO
    ----------------------------------------------------- */

    .site-logo {
        width: 185px;

        flex: 0 0 185px;
    }


    .logo-image {
        width: 185px;
    }


    /* -----------------------------------------------------
       HAMBURGER
    ----------------------------------------------------- */

