    }


    .mobile-dropdown-menu a {
        min-height: 42px;

        font-size: 14px;
    }


    /* -----------------------------------------------------
       ACTIONS
    ----------------------------------------------------- */

    .mobile-header-actions {
        gap: 10px;

        padding-top: 24px;
    }

}


/* =========================================================
   04. IPAD MINI
   481px — 768px
========================================================= */

@media (min-width: 481px) and (max-width: 768px) {

    /* -----------------------------------------------------
       HEADER
    ----------------------------------------------------- */

    .header-container {
        min-height: 72px;

        padding-left: 20px;
        padding-right: 20px;

        gap: 14px;
    }


    /* -----------------------------------------------------
       LOGO
    ----------------------------------------------------- */

    .site-logo {
        width: 160px;

        flex: 0 0 160px;
    }


    .logo-image {
        width: 160px;
    }


    /* -----------------------------------------------------
       HAMBURGER
    ----------------------------------------------------- */

    .hamburger-button {
        width: 46px;
        height: 46px;

        flex: 0 0 46px;
    }


    .hamburger-line {
        width: 20px;
    }


    /* -----------------------------------------------------
       DRAWER
    ----------------------------------------------------- */

    .mobile-navigation {
        width: 380px;

        max-width: 92vw;
    }


    .mobile-navigation-inner {
        padding: 22px;
    }


    /* -----------------------------------------------------
       MENU TITLE
    ----------------------------------------------------- */

    .mobile-menu-title {
        font-size: 20px;
    }


    /* -----------------------------------------------------
       MENU LINKS
    ----------------------------------------------------- */

    .mobile-nav-link {
        min-height: 50px;

        font-size: 16px;
    }


    .mobile-dropdown-menu a {
        min-height: 40px;

        font-size: 14px;
    }


    /* -----------------------------------------------------
       ACTIONS
    ----------------------------------------------------- */

    .mobile-header-actions {
        gap: 10px;

        padding-top: 20px;
    }


    .mobile-header-actions .mobile-action-btn,
    .mobile-header-actions .mobile-quote-btn {
