    }

}


/* =========================================================
   05. MOBILE
   480px AND BELOW
========================================================= */

@media (max-width: 480px) {

    /* -----------------------------------------------------
       HEADER
    ----------------------------------------------------- */

    .header-container {
        min-height: 68px;

        padding-left: 16px;
        padding-right: 16px;

        gap: 12px;
    }


    /* -----------------------------------------------------
       LOGO
    ----------------------------------------------------- */

    .site-logo {
        width: 145px;

        max-width: calc(100% - 58px);

        flex: 0 0 auto;
    }


    .logo-image {
        width: 145px;

        max-width: 100%;
    }


    /* -----------------------------------------------------
       HAMBURGER
    ----------------------------------------------------- */

    .hamburger-button {
        width: 44px;
        height: 44px;

        flex: 0 0 44px;
    }


    .hamburger-line {
        width: 19px;

        height: 2px;
    }


    /* -----------------------------------------------------
       DRAWER
    ----------------------------------------------------- */

    .mobile-navigation {
        width: 100%;

        max-width: 100%;

        border-left: 0;
    }


    .mobile-navigation-inner {
        padding: 18px 16px;
    }


    /* -----------------------------------------------------
       MENU HEADER
    ----------------------------------------------------- */

    .mobile-menu-header {
        min-height: 50px;

        padding-bottom: 12px;
    }


    .mobile-menu-title {
        font-size: 19px;
    }


    .mobile-menu-close {
        width: 40px;
        height: 40px;

        font-size: 17px;
    }


    /* -----------------------------------------------------
       MOBILE NAVIGATION
    ----------------------------------------------------- */

    .mobile-menu {
        padding-top: 8px;
    }


    .mobile-nav-link {
        min-height: 48px;

        padding: 11px 2px;

        font-size: 15px;
    }


    .mobile-dropdown-menu {
        padding-left: 12px;
    }


    .mobile-dropdown-menu a {
        min-height: 39px;

        padding: 7px 10px;

        font-size: 13px;
    }


    /* -----------------------------------------------------
       MOBILE ACTIONS
    ----------------------------------------------------- */

    .mobile-header-actions {
        gap: 8px;

        padding-top: 16px;

        margin-top: auto;
    }


    .mobile-action-btn {
        min-height: 46px;

        padding: 9px 13px;

        font-size: 14px;
    }


    .mobile-header-actions .rtl-btn,
    .mobile-header-actions .dark-mode-btn {
        height: 46px;

        min-height: 46px;

        padding: 0;
    }


    .mobile-quote-btn {
        min-height: 48px;

        font-size: 14px;
    }

}


/* =========================================================
   06. VERY SMALL MOBILE
   360px AND BELOW
========================================================= */

@media (max-width: 360px) {

    /* -----------------------------------------------------
       HEADER
    ----------------------------------------------------- */

    .header-container {
        min-height: 64px;

        padding-left: 12px;
        padding-right: 12px;

        gap: 10px;
    }


    /* -----------------------------------------------------
       LOGO
    ----------------------------------------------------- */

    .site-logo {
        width: 135px;
    }


    .logo-image {
        width: 135px;
    }


    /* -----------------------------------------------------
       HAMBURGER
    ----------------------------------------------------- */

    .hamburger-button {
        width: 42px;
        height: 42px;

        flex-basis: 42px;
    }


    .hamburger-line {
        width: 18px;
    }


    /* -----------------------------------------------------
       DRAWER
    ----------------------------------------------------- */

    .mobile-navigation-inner {
        padding: 16px 14px;
    }


    /* -----------------------------------------------------
       MENU
    ----------------------------------------------------- */

    .mobile-nav-link {
        min-height: 46px;

        font-size: 14px;
    }


    .mobile-dropdown-menu a {
        font-size: 13px;
    }


    /* -----------------------------------------------------
       ACTIONS
    ----------------------------------------------------- */

    .mobile-header-actions {
        gap: 7px;
    }

}


/* =========================================================
   07. RESPONSIVE TYPOGRAPHY
========================================================= */


/* ---------------------------------------------------------
   IPAD PRO
--------------------------------------------------------- */

@media (min-width: 769px) and (max-width: 1199px) {

    :root {

        --fs-h1: 40px;
        --fs-h2: 32px;
        --fs-h3: 22px;
        --fs-h4: 19px;

        --fs-body: 16px;
        --fs-small: 14px;
        --fs-label: 13px;
        --fs-button: 15px;
        --fs-nav: 15px;
    }

}


/* ---------------------------------------------------------
   IPAD MINI + MOBILE
--------------------------------------------------------- */

@media (max-width: 768px) {

    :root {

        --fs-h1: 32px;
        --fs-h2: 28px;
        --fs-h3: 20px;
        --fs-h4: 18px;

        --fs-body: 15px;
        --fs-small: 13px;
        --fs-label: 12px;
        --fs-button: 14px;
        --fs-nav: 14px;
    }

}


/* =========================================================
   08. MOBILE DROPDOWNS
========================================================= */

@media (max-width: 1199px) {

    .mobile-nav-item.has-mobile-dropdown {
        position: relative;
    }


    .mobile-dropdown-toggle {
        cursor: pointer;
    }


    .mobile-dropdown-menu {
        width: 100%;

        max-height: 0;

        overflow: hidden;

        opacity: 0;

        transition:
            max-height 0.3s ease,
            opacity 0.3s ease;
    }


    .has-mobile-dropdown.active
    .mobile-dropdown-menu {

        max-height: 600px;

        opacity: 1;
    }

}


/* =========================================================
   09. RTL RESPONSIVE
========================================================= */

@media (max-width: 1199px) {

    /* -----------------------------------------------------
       HEADER
    ----------------------------------------------------- */

    html[dir="rtl"] .header-container {
        direction: rtl;
    }


    /* -----------------------------------------------------
       HAMBURGER

       In RTL, hamburger moves to left.
    ----------------------------------------------------- */

    html[dir="rtl"] .hamburger-button {
        margin-left: 0;

        margin-right: auto;
    }


    /* -----------------------------------------------------
       DRAWER

       LTR:
       right side

       RTL:
       left side
    ----------------------------------------------------- */

    html[dir="rtl"] .mobile-navigation {
        right: auto;

        left: 0;

        transform: translateX(-100%);

        border-right: 1px solid var(--color-border);

        border-left: 0;
    }


    html[dir="rtl"]
    .mobile-navigation.active {
        transform: translateX(0);
    }


    /* -----------------------------------------------------
       MOBILE MENU
    ----------------------------------------------------- */

    html[dir="rtl"] .mobile-menu {
        direction: rtl;
    }


    html[dir="rtl"] .mobile-nav-link {
        text-align: right;
    }


    /* -----------------------------------------------------
       MOBILE DROPDOWN
    ----------------------------------------------------- */

    html[dir="rtl"] .mobile-dropdown-menu {
        padding-left: 0;

        padding-right: 12px;
    }


    html[dir="rtl"] .mobile-dropdown-menu a {
        border-left: 0;

        border-right: 2px solid transparent;
    }


    html[dir="rtl"]
    .mobile-dropdown-menu a:hover,
    html[dir="rtl"]
    .mobile-dropdown-menu a:focus-visible {

        border-right-color: var(--color-orange);

        border-left-color: transparent;
    }


    /* -----------------------------------------------------
       MOBILE ACTIONS
    ----------------------------------------------------- */

    html[dir="rtl"] .mobile-header-actions {
        direction: rtl;
    }

}


/* =========================================================
   10. RTL MOBILE
========================================================= */

@media (max-width: 480px) {

    html[dir="rtl"] .mobile-dropdown-menu {
        padding-right: 12px;

        padding-left: 0;
    }

}


/* =========================================================
   11. DARK MODE RESPONSIVE
========================================================= */

@media (max-width: 1199px) {

    /* -----------------------------------------------------
       DRAWER
    ----------------------------------------------------- */

    body.dark-mode .mobile-navigation {
        background-color: #121212;

        border-color: #303030;

        box-shadow:
            -10px 0 35px rgba(0, 0, 0, 0.40);
    }


    body.dark-mode .mobile-menu-title,
    body.dark-mode .mobile-nav-link,
    body.dark-mode .mobile-nav-link span,
    body.dark-mode .mobile-dropdown-menu a,
    body.dark-mode .mobile-dropdown-menu a span {
        color: #f5f5f5;
    }


    body.dark-mode .mobile-dropdown-menu a {
        color: #d6d6d6;
    }


    /* -----------------------------------------------------
       HAMBURGER
    ----------------------------------------------------- */

    body.dark-mode .hamburger-button {
        color: #f1f1f1;

        background-color: #1c1c1c;

        border-color: #383838;
    }


    body.dark-mode .hamburger-button:hover,
    body.dark-mode .hamburger-button:focus-visible {

        color: var(--color-orange-light);

        background-color: #252525;

        border-color: var(--color-orange-light);
    }


    /* -----------------------------------------------------
       CLOSE BUTTON
    ----------------------------------------------------- */

    body.dark-mode .mobile-menu-close {
        color: #f1f1f1;

        background-color: #1c1c1c;

        border-color: #383838;
    }


    body.dark-mode .mobile-menu-close:hover,
    body.dark-mode .mobile-menu-close:focus-visible {

        color: var(--color-orange-light);

        background-color: #252525;

        border-color: var(--color-orange-light);
    }


    /* -----------------------------------------------------
       MOBILE ACTION BUTTONS
    ----------------------------------------------------- */

    body.dark-mode
    .mobile-header-actions
    .rtl-btn,

    body.dark-mode
    .mobile-header-actions
    .dark-mode-btn {

        color: #f1f1f1;

        background-color: #222222;

        border-color: #383838;
    }


    body.dark-mode
    .mobile-header-actions
    .rtl-btn:hover,

    body.dark-mode
    .mobile-header-actions
    .dark-mode-btn:hover {

        color: var(--color-orange-light);

        background-color: #2b2b2b;

        border-color: var(--color-orange-light);
    }

}


/* =========================================================
   12. LANDSCAPE MOBILE
========================================================= */

@media (max-width: 768px)
and (orientation: landscape) {

    .mobile-navigation-inner {
        padding-top: 14px;

        padding-bottom: 14px;
    }


    .mobile-menu-header {
        min-height: 46px;
    }


    .mobile-nav-link {
        min-height: 42px;

        padding-top: 8px;

        padding-bottom: 8px;
    }


    .mobile-header-actions {
        padding-top: 12px;
    }

}


/* =========================================================
   13. TOUCH DEVICES
========================================================= */

@media (hover: none) and (pointer: coarse) {

    .nav-link:hover {
        background-color: transparent;
    }


    .header-action-btn:hover {
        transform: none;
    }


    .primary-btn:hover,
    .secondary-btn:hover {
        transform: none;

        box-shadow: none;
    }


    .mobile-nav-link:hover {
        background-color: transparent;
    }

}


/* =========================================================
   14. REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .mobile-navigation,
    .mobile-dropdown-menu,
    .hamburger-line {
        transition: none !important;
    }

}


/* =========================================================
   END OF RESPONSIVE CSS
========================================================= */


/* =========================================================
   PAINTCRAFT FOOTER
   PART 3 — RESPONSIVE + RTL
========================================================= */


/* =========================================================
   DESKTOP — 1200px AND ABOVE
========================================================= */

@media (min-width: 1200px) {

    .footer-main .footer-container {
        grid-template-columns:
            1.35fr
            1fr
            1fr
            1.25fr;
    }

    .footer-cta-inner {
        min-height: 55px;
    }

}


/* =========================================================
   IPAD PRO
   769px — 1199px
========================================================= */

@media (min-width: 769px) and (max-width: 1199px) {

    .footer-main {
        padding: 60px 0 45px;
    }

    .footer-main .footer-container {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 45px 40px;
    }

    .footer-brand {
        grid-column: 1 / -1;
    }

    .footer-description {
        max-width: 600px;
    }

    .footer-cta-inner {
        flex-direction: row;
        align-items: center;
    }

    .footer-bottom-inner {
        flex-direction: row;
        align-items: center;
    }

}


/* =========================================================
   IPAD MINI
   481px — 768px
========================================================= */

@media (min-width: 481px) and (max-width: 768px) {

    .footer-container {
        padding-left: 25px;
        padding-right: 25px;
    }

    .footer-main {
        padding: 55px 0 40px;
    }

    .footer-main .footer-container {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 40px 30px;
    }

    .footer-brand {
        grid-column: 1 / -1;
    }

    .footer-description {
        max-width: 580px;
    }

    .footer-cta-inner {
        flex-direction: column;
        align-items: flex-start;
        gap: 20px;
    }

    .footer-cta-button {
        width: auto;
    }

    .footer-bottom-inner {
        flex-direction: column;
        align-items: flex-start;
        gap: 12px;
    }

}


/* =========================================================
   MOBILE
   0px — 480px
========================================================= */

@media (max-width: 480px) {

    .footer-container {
        padding-left: 20px;
        padding-right: 20px;
    }

    .footer-main {
        padding: 48px 0 35px;
    }

    .footer-main .footer-container {
        grid-template-columns: 1fr;
        gap: 35px;
    }

    .footer-brand {
        grid-column: auto;
    }

    .footer-description {
        max-width: 100%;
    }

    .footer-cta-inner {
        flex-direction: column;
        align-items: stretch;
        gap: 20px;
    }

    .footer-cta-button {
        width: 100%;
    }

    .footer-bottom-inner {
        flex-direction: column;
        align-items: flex-start;
        gap: 12px;
    }

    .footer-legal-links {
        flex-wrap: wrap;
        gap: 10px 18px;
    }

}


/* =========================================================
   SMALL MOBILE
   0px — 360px
========================================================= */

@media (max-width: 360px) {

    .footer-container {
        padding-left: 16px;
        padding-right: 16px;
    }

    .footer-main {
        padding: 42px 0 32px;
    }

    .footer-main .footer-container {
        gap: 30px;
    }

    .footer-cta {
        padding: 25px 0;
    }

    .footer-bottom {
        padding: 16px 0;
    }

}


/* =========================================================
   LANDSCAPE MOBILE
========================================================= */

@media (max-width: 768px) and (orientation: landscape) {

    .footer-main {
        padding-top: 42px;
        padding-bottom: 35px;
    }

    .footer-main .footer-container {
        gap: 30px;
    }

}


/* =========================================================
   RTL — ALL RESPONSIVE DEVICES
========================================================= */

html[dir="rtl"] .footer-main .footer-container,
body.rtl .footer-main .footer-container {
    direction: rtl;
}

