/* =========================================================
   HOME 1
   SECTION 3 — ABOUT PAINTCRAFT
   PART 2 — MAIN CSS
========================================================= */


/* =========================================================
   ABOUT SECTION
========================================================= */

.about-section {
    width: 100%;
    padding: 90px 0;

    background: var(--color-bg);
}

.about-container {
    width: 100%;
    max-width: 1700px;

    margin: 0 auto;
    padding: 0 30px;

    display: grid;
    grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);

    align-items: center;
    gap: 80px;
}


/* =========================================================
   ABOUT IMAGE
========================================================= */

.about-image-wrapper {
    position: relative;

    width: 100%;
    max-width: 680px;

    margin: 0 auto;
}

.about-image-main {
    position: relative;

    width: 100%;
    aspect-ratio: 4 / 4.6;

    overflow: hidden;

    border-radius: 18px;
}

.about-image {
    display: block;

    width: 100%;
    height: 100%;

    object-fit: cover;

    transition: transform 0.5s ease;
}

.about-image-main:hover .about-image {
    transform: scale(1.03);
}


/* =========================================================
   EXPERIENCE BADGE
========================================================= */

.about-experience-badge {
    position: absolute;

    right: -25px;
    bottom: 35px;

    width: 150px;
    min-height: 150px;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    padding: 20px;

    border: 8px solid var(--color-bg);
    border-radius: 50%;

    background: var(--color-primary);
    color: #ffffff;

    text-align: center;

    box-shadow: 0 12px 30px rgba(0, 0, 0, 0.12);
}

.about-experience-badge strong {
    display: block;

    margin-bottom: 3px;

    color: #ffffff;

    font-family: "Inter", sans-serif;
    font-size: 32px;
    font-weight: 800;
    line-height: 1;
}

.about-experience-badge span {
    display: block;

    color: rgba(255, 255, 255, 0.95);

    font-family: "Inter", sans-serif;
    font-size: 12px;
    font-weight: 600;
    line-height: 1.4;

    text-transform: uppercase;
}


/* =========================================================
   ABOUT CONTENT
========================================================= */

.about-content {
    width: 100%;
    max-width: 720px;
}

.about-subtitle {
    display: inline-block;

    margin-bottom: 14px;

    color: var(--color-primary);

    font-family: "Inter", sans-serif;
    font-size: 14px;
    font-weight: 700;
    line-height: 1.5;

    letter-spacing: 1px;
    text-transform: uppercase;
}

.about-title {
    margin: 0;

    color: var(--color-text);

    font-family: "Inter", sans-serif;
    font-size: 44px;
    font-weight: 800;
    line-height: 1.2;

    letter-spacing: -0.8px;
}

.about-title span {
    color: var(--color-primary);
}

.about-description {
    max-width: 680px;

    margin: 20px 0 30px;

    color: var(--color-text-muted);

    font-family: "Inter", sans-serif;
    font-size: 16px;
    font-weight: 400;
    line-height: 1.8;
}


/* =========================================================
   ABOUT FEATURES
========================================================= */

.about-features {
    display: grid;

    grid-template-columns: repeat(2, minmax(0, 1fr));

    gap: 22px 28px;

    margin-bottom: 30px;
}

.about-feature {
    display: flex;
    align-items: flex-start;

    gap: 13px;

    min-width: 0;
}

.about-feature-icon {
    flex: 0 0 42px;

    width: 42px;
    height: 42px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 8px;

    background: rgba(255, 90, 54, 0.10);
    color: var(--color-primary);

    font-size: 16px;
}

.about-feature-content {
    min-width: 0;
}

.about-feature-content h3 {
    margin: 0 0 4px;

    color: var(--color-text);

    font-family: "Inter", sans-serif;
    font-size: 14px;
    font-weight: 700;
    line-height: 1.45;
}

.about-feature-content p {
    margin: 0;

    color: var(--color-text-muted);

    font-family: "Inter", sans-serif;
    font-size: 13px;
    font-weight: 400;
    line-height: 1.55;
}


/* =========================================================
   ABOUT BUTTON
========================================================= */

.about-action {
    display: flex;
    align-items: center;
}

.about-button {
    min-height: 48px;

    display: inline-flex;
    align-items: center;
    justify-content: center;

    gap: 10px;

    padding: 0 24px;

    border: 2px solid var(--color-primary);
    border-radius: 8px;

    background: var(--color-primary);
    color: #ffffff;

    font-family: "Inter", sans-serif;
    font-size: 14px;
    font-weight: 700;

    text-decoration: none;
    white-space: nowrap;

    transition:
        background-color 0.25s ease,
        border-color 0.25s ease,
        color 0.25s ease,
        transform 0.25s ease;
}

.about-button i {
    font-size: 13px;

    transition: transform 0.25s ease;
}

.about-button:hover {
    background: var(--color-primary-light);
    border-color: var(--color-primary-light);
    color: #ffffff;

    transform: translateY(-2px);
}

.about-button:hover i {
    transform: translateX(3px);
}


/* =========================================================
   DARK MODE
========================================================= */

body.dark-mode .about-section {
    background: var(--color-bg);
}

body.dark-mode .about-experience-badge {
    border-color: var(--color-bg);
}

body.dark-mode .about-feature-icon {
    background: rgba(233, 74, 40, 0.12);
}

body.dark-mode .about-button:hover {
    background: var(--color-primary-light);
    border-color: var(--color-primary-light);
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .about-section,
body.rtl .about-section {
    direction: rtl;
}

html[dir="rtl"] .about-container,
body.rtl .about-container {
    direction: rtl;
}

html[dir="rtl"] .about-experience-badge,
body.rtl .about-experience-badge {
    right: auto;
    left: -25px;
}

html[dir="rtl"] .about-feature,
body.rtl .about-feature {
    direction: rtl;
}

html[dir="rtl"] .about-action,
body.rtl .about-action {
    direction: rtl;
}

html[dir="rtl"] .about-button i,
body.rtl .about-button i {
    transform: rotate(180deg);
}

html[dir="rtl"] .about-button:hover i,
body.rtl .about-button:hover i {
    transform: rotate(180deg) translateX(3px);
}


/* =========================================================
   ACCESSIBILITY
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .about-image,
    .about-button,
    .about-button i {
        transition: none;
