========================================================= */

.color-consultation-benefits {
    display: flex;
    flex-direction: column;
    gap: 22px;
    margin-top: 32px;
}

.color-consultation-benefit {
    display: flex;
    align-items: flex-start;
    gap: 16px;
}

.benefit-icon {
    flex: 0 0 48px;
    width: 48px;
    height: 48px;

    display: inline-flex;
    align-items: center;
    justify-content: center;

    background: rgba(255, 90, 54, 0.10);
    color: var(--color-primary);

    border-radius: 12px;

    font-size: 18px;
}

.benefit-icon i {
    color: var(--color-primary);
    font-size: 18px;
    line-height: 1;
}

.benefit-content {
    min-width: 0;
}

.benefit-content h3 {
