    max-width: 560px;
    margin: 5px 0 0;

    color: var(--color-text-muted);
    font-family: "Inter", sans-serif;
    font-size: 14px;
    font-weight: 400;
    line-height: 1.6;
}


/* =========================================================
   ACTION BUTTONS
========================================================= */

.color-consultation-actions {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 14px;
    margin-top: 34px;
}


/* Primary Button */

.color-consultation-actions .primary-button {
    min-height: 48px;
    padding: 0 22px;

    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 9px;

    background: var(--color-primary);
    color: #ffffff;

    border: 2px solid var(--color-primary);
    border-radius: 8px;

    font-family: "Inter", sans-serif;
    font-size: 14px;
    font-weight: 700;
    line-height: 1;

    text-decoration: none;

    transition:
        background 0.25s ease,
        border-color 0.25s ease,
        color 0.25s ease,
        transform 0.25s ease;
}

.color-consultation-actions .primary-button i {
    color: #ffffff;
    font-size: 14px;
}

.color-consultation-actions .primary-button:hover {
    background: var(--color-primary-dark, #e94a28);
    border-color: var(--color-primary-dark, #e94a28);
    transform: translateY(-2px);
}


/* Secondary Button */

.color-consultation-actions .secondary-button {
    min-height: 48px;
    padding: 0 22px;

    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 9px;

    background: transparent;
    color: var(--color-primary);

    border: 2px solid var(--color-primary);
    border-radius: 8px;

    font-family: "Inter", sans-serif;
    font-size: 14px;
    font-weight: 700;
    line-height: 1;

    text-decoration: none;

    transition:
        background 0.25s ease,
        color 0.25s ease,
        border-color 0.25s ease,
        transform 0.25s ease;
}

.color-consultation-actions .secondary-button i {
    color: var(--color-primary);
    font-size: 14px;
}

.color-consultation-actions .secondary-button:hover {
    background: var(--color-primary);
    color: #ffffff;
    border-color: var(--color-primary);
    transform: translateY(-2px);
}

.color-consultation-actions .secondary-button:hover i {
    color: #ffffff;
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .color-consultation-content {
    text-align: right;
}

html[dir="rtl"] .color-consultation-benefit {
    flex-direction: row;
}

