/* =========================================================
   HOME 2
   SECTION 4: SPACES WE TRANSFORM
   PART 2 - MAIN CSS
========================================================= */

.home2-spaces-section {
    width: 100%;
    padding: 100px 0;
    background: var(--color-bg);
    overflow: hidden;
}

.home2-spaces-container {
    width: 100%;
    max-width: 1700px;
    margin: 0 auto;
    padding: 0 30px;
}


/* =========================================================
   SECTION HEADER
========================================================= */

.home2-spaces-header {
    width: 100%;
    max-width: 850px;
    margin: 0 auto 65px;
    text-align: center;
}

.home2-spaces-eyebrow {
    display: block;
    margin: 0 0 14px;
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 800;
    line-height: 1.4;
    letter-spacing: 2.5px;
    text-transform: uppercase;
}

.home2-spaces-title {
    margin: 0;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 46px;
    font-weight: 800;
    line-height: 1.15;
    letter-spacing: -1.2px;
}

.home2-spaces-title span {
    color: var(--color-orange);
}

.home2-spaces-description {
    max-width: 700px;
    margin: 20px auto 0;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 17px;
    font-weight: 400;
    line-height: 1.7;
}


/* =========================================================
   SPACES GRID
========================================================= */

.home2-spaces-grid {
    width: 100%;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 55px;
    align-items: start;
}


/* =========================================================
   SPACE CARD
========================================================= */

.home2-space-card {
    min-width: 0;
    text-align: center;
    position: relative;
}

.home2-space-image-link {
    display: block;
    width: 100%;
    text-decoration: none;
}

.home2-space-image-wrapper {
    position: relative;
    width: 100%;
    max-width: 330px;
    aspect-ratio: 1 / 1;
    margin: 0 auto;
    overflow: hidden;
    border-radius: 50%;
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    box-shadow: 0 12px 35px rgba(0, 0, 0, 0.08);
}

.home2-space-image {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition:
        transform 0.5s ease,
        filter 0.5s ease;
}

.home2-space-image-overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(
        180deg,
        rgba(0, 0, 0, 0) 45%,
        rgba(0, 0, 0, 0.18) 100%
    );
    opacity: 0;
    transition: opacity 0.4s ease;
    pointer-events: none;
}


/* =========================================================
   IMAGE HOVER
========================================================= */

.home2-space-card:hover .home2-space-image {
    transform: scale(1.08);
}

.home2-space-card:hover .home2-space-image-overlay {
    opacity: 1;
}


/* =========================================================
   CARD CONTENT
========================================================= */

.home2-space-content {
    width: 100%;
    max-width: 430px;
    margin: 35px auto 0;
    text-align: center;
}

.home2-space-category {
    display: block;
    margin: 0 0 12px;
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 700;
    line-height: 1.4;
    letter-spacing: 1.4px;
    text-transform: uppercase;
}

.home2-space-title {
    margin: 0;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 27px;
    font-weight: 750;
    line-height: 1.25;
    letter-spacing: -0.4px;
}

.home2-space-description {
    max-width: 390px;
    margin: 18px auto 0;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 16px;
    font-weight: 400;
    line-height: 1.7;
}


/* =========================================================
   CIRCULAR ARROW BUTTON
========================================================= */

.home2-space-arrow {
    width: 58px;
    height: 58px;
    margin: 28px auto 0;

    display: flex;
    align-items: center;
    justify-content: center;

    border: 1px solid var(--color-border);
    border-radius: 50%;

    background: var(--color-bg);
    color: var(--color-text);

    text-decoration: none;

    transition:
        background 0.3s ease,
        color 0.3s ease,
        border-color 0.3s ease,
        transform 0.3s ease,
        box-shadow 0.3s ease;
}

.home2-space-arrow i {
    font-size: 17px;
    line-height: 1;
    transition: transform 0.3s ease;
}

.home2-space-arrow:hover {
    background: var(--color-orange);
    border-color: var(--color-orange);
    color: #ffffff;
    transform: translateY(-4px);
    box-shadow: 0 10px 25px rgba(255, 90, 54, 0.25);
}

.home2-space-arrow:hover i {
    transform: translateX(3px);
}


/* =========================================================
   DARK MODE
========================================================= */

body.dark-mode .home2-spaces-section {
    background: var(--color-bg);
}

body.dark-mode .home2-space-image-wrapper {
    background: var(--color-surface);
    border-color: var(--color-border);
    box-shadow: 0 12px 35px rgba(0, 0, 0, 0.25);
}

body.dark-mode .home2-space-arrow {
    background: var(--color-surface);
    border-color: var(--color-border);
    color: var(--color-text);
}

body.dark-mode .home2-space-arrow:hover {
    background: var(--color-orange);
    border-color: var(--color-orange);
    color: #ffffff;
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .home2-spaces-section {
    direction: rtl;
}

html[dir="rtl"] .home2-space-description {
    text-align: center;
}

html[dir="rtl"] .home2-space-arrow:hover i {
    transform: translateX(-3px);
}


/* =========================================================
   TOUCH DEVICES
========================================================= */

@media (hover: none) {

    .home2-space-card:hover .home2-space-image {
        transform: none;
    }

    .home2-space-card:hover .home2-space-image-overlay {
        opacity: 0;
    }

    .home2-space-arrow:hover {
        transform: none;
        box-shadow: none;
    }

    .home2-space-arrow:hover i {
        transform: none;
    }
}


/* =========================================================
   ACCESSIBILITY
========================================================= */

.home2-space-image-link:focus-visible,
.home2-space-arrow:focus-visible {
    outline: 3px solid rgba(255, 90, 54, 0.35);
    outline-offset: 5px;
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .home2-space-image,
    .home2-space-image-overlay,
    .home2-space-arrow,
    .home2-space-arrow i {
        transition: none;
    }
}

