    padding: 100px 0;
    background: var(--color-surface);
    overflow: hidden;
}

.home2-projects-container {
    width: 100%;
    max-width: 1700px;
    margin: 0 auto;
    padding: 0 30px;
    box-sizing: border-box;
}


/* =========================================================
   SECTION HEADER - CENTERED
========================================================= */

.home2-projects-header {
    width: 100%;
    max-width: 1050px;
    margin: 0 auto 65px;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    text-align: center;
    box-sizing: border-box;
}


/* =========================================================
   HEADING
========================================================= */

.home2-projects-heading {
    width: 100%;
    max-width: 900px;
    margin: 0 auto;
    text-align: center;
}

.home2-projects-eyebrow {
    display: block;

    margin: 0 0 14px;

    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 800;
    line-height: 1.4;
    letter-spacing: 2.8px;
    text-transform: uppercase;
}

.home2-projects-title {
    width: 100%;
    max-width: 900px;
    margin: 0 auto;

    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 46px;
    font-weight: 800;
    line-height: 1.15;
    letter-spacing: -1.2px;

    text-align: center;
    box-sizing: border-box;
}

.home2-projects-title span {
    color: var(--color-orange);
}


/* =========================================================
   INTRO CONTENT - CENTERED
========================================================= */

.home2-projects-intro {
    width: 100%;
    max-width: 850px;

    margin: 22px auto 0;

    display: flex;
    align-items: center;
    justify-content: center;

    gap: 30px;

    text-align: center;
    box-sizing: border-box;
}

.home2-projects-intro p {
    width: 100%;
    max-width: 600px;
    margin: 0;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 16px;
    font-weight: 400;
    line-height: 1.7;

    text-align: center;
}


/* =========================================================
   MORE PROJECTS BUTTON
========================================================= */

.home2-projects-gallery-button {
    flex: 0 0 auto;

    min-height: 54px;

    padding: 7px 20px 7px 8px;

    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 12px;

    border: 2px solid var(--color-orange);
    border-radius: 40px;

    background: var(--color-orange);
    color: #ffffff;

    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 750;
    line-height: 1;
    letter-spacing: 0.3px;

    text-decoration: none;
    text-transform: uppercase;
    white-space: nowrap;

    box-sizing: border-box;

    transition:
        background 0.3s ease,
        color 0.3s ease,
        border-color 0.3s ease,
        transform 0.3s ease,
        box-shadow 0.3s ease;
}

.home2-projects-gallery-icon {
    flex: 0 0 38px;

    width: 38px;
    height: 38px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: #ffffff;
    color: var(--color-orange);

    transition: transform 0.3s ease;
}

.home2-projects-gallery-icon i {
    font-size: 14px;
    line-height: 1;
}

.home2-projects-gallery-button:hover {
    background: transparent;
    color: var(--color-orange);

    transform: translateY(-3px);

    box-shadow:
        0 10px 25px rgba(255, 90, 54, 0.16);
}

.home2-projects-gallery-button:hover .home2-projects-gallery-icon {
    transform: translateX(3px);
}


/* =========================================================
   PROJECT GALLERY
========================================================= */

.home2-projects-gallery {
    width: 100%;
    max-width: 1500px;

    margin: 0 auto;

    display: grid;

    grid-template-columns:
        minmax(0, 1fr)
        minmax(0, 1fr)
        minmax(0, 1fr);

    column-gap: 24px;
    row-gap: 45px;

    align-items: start;

    box-sizing: border-box;
}


/* =========================================================
   PROJECT CARD
========================================================= */

.home2-project-card {
    width: 100%;
    min-width: 0;

    position: relative;

    margin: 0;
    padding: 0;

    box-sizing: border-box;
}

.home2-project-link {
    display: block;

    width: 100%;
    margin: 0;
    padding: 0;

    color: inherit;
    text-decoration: none;

    box-sizing: border-box;
}


/* =========================================================
   PROJECT IMAGE
========================================================= */

.home2-project-image-wrapper {
    position: relative;

    width: 100%;
    height: 520px;

    margin: 0;
    padding: 0;

    overflow: hidden;

    background: var(--color-bg);

    box-sizing: border-box;
}

.home2-project-card-medium .home2-project-image-wrapper {
    height: 410px;
}

.home2-project-card-tall .home2-project-image-wrapper {
    height: 520px;
}

.home2-project-image {
    display: block;

    width: 100%;
    height: 100%;

    margin: 0;
    padding: 0;

    object-fit: cover;

    transition:
        transform 0.6s ease,
        filter 0.5s ease;
}


/* =========================================================
   ORANGE HOVER OVERLAY
========================================================= */

.home2-project-overlay {
    position: absolute;
    inset: 0;

    width: 100%;
    height: 100%;

    background: rgba(255, 90, 54, 0.76);

    opacity: 0;
    pointer-events: none;

    transition: opacity 0.4s ease;
}


/* =========================================================
   VIEW CIRCLE
========================================================= */

.home2-project-view {
    position: absolute;

    top: 50%;
    left: 50%;

    width: 92px;
    height: 92px;

    display: flex;
    align-items: center;
    justify-content: center;

    margin: 0;
    padding: 0;

    border-radius: 50%;

    background: #ffffff;
    color: var(--color-orange);

    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 800;
    line-height: 1;
    letter-spacing: 1px;

    transform:
        translate(-50%, -50%)
        scale(0.65);

    opacity: 0;
    visibility: hidden;

    transition:
        opacity 0.35s ease,
        visibility 0.35s ease,
        transform 0.4s ease;
}


/* =========================================================
   HOVER
========================================================= */

.home2-project-card:hover .home2-project-image {
    transform: scale(1.06);
    filter: saturate(1.05);
}

.home2-project-card:hover .home2-project-overlay {
    opacity: 1;
}

.home2-project-card:hover .home2-project-view {
    opacity: 1;
    visibility: visible;

    transform:
        translate(-50%, -50%)
        scale(1);
}


/* =========================================================
   PROJECT INFORMATION
========================================================= */

.home2-project-info {
    width: 100%;

    margin: 0;
    padding: 18px 4px 0;

    box-sizing: border-box;
}

.home2-project-info span {
    display: block;

    margin: 0 0 7px;

    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 750;
    line-height: 1.4;
    letter-spacing: 1.5px;
}

.home2-project-info h3 {
    width: 100%;

    margin: 0;

    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 21px;
    font-weight: 750;
    line-height: 1.3;
}


/* =========================================================
   STAGGERED GALLERY
========================================================= */

.home2-project-card:nth-child(1) {
    margin-top: 0;
}

.home2-project-card:nth-child(2) {
    margin-top: 70px;
}

.home2-project-card:nth-child(3) {
    margin-top: 0;
}

.home2-project-card:nth-child(4) {
    margin-top: 45px;
}

.home2-project-card:nth-child(5) {
    margin-top: 0;
}

.home2-project-card:nth-child(6) {
    margin-top: 70px;
}


/* =========================================================
   DARK MODE
========================================================= */

body.dark-mode .home2-projects-section {
    background: var(--color-surface);
}

body.dark-mode .home2-project-image-wrapper {
    background: var(--color-bg);
}

body.dark-mode .home2-project-view {
    background: var(--color-bg);
    color: var(--color-orange);
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .home2-projects-section {
    direction: rtl;
}

html[dir="rtl"] .home2-projects-header {
    direction: rtl;
    text-align: center;
}

html[dir="rtl"] .home2-projects-heading,
html[dir="rtl"] .home2-projects-title,
html[dir="rtl"] .home2-projects-intro,
html[dir="rtl"] .home2-projects-intro p {
    text-align: center;
}

html[dir="rtl"] .home2-projects-gallery-button {
    padding: 7px 8px 7px 20px;
}

html[dir="rtl"] .home2-projects-gallery-icon {
    order: 2;
}

html[dir="rtl"] .home2-projects-gallery-button:hover .home2-projects-gallery-icon {
    transform: translateX(-3px);
}


/* =========================================================
   TOUCH DEVICES
========================================================= */

@media (hover: none) and (pointer: coarse) {

    .home2-project-card:hover .home2-project-image {
        transform: none;
        filter: none;
    }

    .home2-project-card:hover .home2-project-overlay {
        opacity: 0;
    }

    .home2-project-card:hover .home2-project-view {
        opacity: 0;
        visibility: hidden;

        transform:
            translate(-50%, -50%)
            scale(0.65);
    }

    .home2-projects-gallery-button:hover {
        transform: none;
        box-shadow: none;
    }

}


/* =========================================================
   ACCESSIBILITY
========================================================= */

.home2-project-link:focus-visible {
    outline: 3px solid rgba(255, 90, 54, 0.35);
    outline-offset: 6px;
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .home2-project-image,
    .home2-project-overlay,
    .home2-project-view,
    .home2-projects-gallery-button,
    .home2-projects-gallery-icon {
        transition: none;
    }

}

/* =========================================================
   HOME 2
   SECTION 7: PAINT GALLERY
   PART 2 - MAIN CSS
========================================================= */

.home2-color-gallery-section {
    width: 100%;
    padding: 100px 0;
    background: var(--color-bg);
    overflow: hidden;
}

.home2-color-gallery-container {
    width: 100%;
    max-width: 1700px;
    margin: 0 auto;
    padding: 0 30px;
    box-sizing: border-box;
}


/* =========================================================
   SECTION HEADER
========================================================= */

.home2-color-gallery-header {
    width: 100%;
    max-width: 850px;
    margin: 0 auto 65px;
    text-align: center;
}

.home2-color-gallery-eyebrow {
    display: block;
    margin: 0 0 14px;

    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 800;
    line-height: 1.4;
    letter-spacing: 3px;
    text-transform: uppercase;
}

.home2-color-gallery-title {
    margin: 0;

    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 46px;
    font-weight: 800;
    line-height: 1.15;
    letter-spacing: -1.2px;
}

.home2-color-gallery-title span {
    color: var(--color-orange);
}

.home2-color-gallery-description {
    max-width: 680px;
    margin: 18px auto 0;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 16px;
    font-weight: 400;
    line-height: 1.7;
}


/* =========================================================
   MASONRY GALLERY
========================================================= */

.home2-color-gallery {
    width: 100%;
    max-width: 1550px;
    margin: 0 auto;

    display: grid;
    grid-template-columns:
        minmax(0, 0.82fr)
        minmax(0, 0.82fr)
        minmax(0, 1.45fr);

    grid-template-rows: 410px 410px;

    gap: 24px;

    align-items: stretch;
    box-sizing: border-box;
}


/* =========================================================
   COLOR CARD
========================================================= */

.home2-color-card {
    position: relative;
    min-width: 0;
    width: 100%;
    height: 100%;

    margin: 0;
    padding: 0;

    overflow: hidden;

    box-sizing: border-box;
}

.home2-color-image-wrapper {
    position: relative;

    width: 100%;
    height: 100%;

    overflow: hidden;

    background: var(--color-surface);
}

.home2-color-image {
    display: block;

    width: 100%;
    height: 100%;

    margin: 0;
    padding: 0;

    object-fit: cover;

    transition:
        transform 0.7s ease,
        filter 0.5s ease;
}


/* =========================================================
   GALLERY POSITIONING
========================================================= */

/* Left top */
.home2-color-card:nth-child(1) {
    grid-column: 1;
    grid-row: 1;
}

/* Center tall */
.home2-color-card:nth-child(2) {
    grid-column: 2;
    grid-row: 1 / 3;
}

/* Right wide top */
.home2-color-card:nth-child(3) {
    grid-column: 3;
    grid-row: 1;
}

/* Left bottom */
.home2-color-card:nth-child(4) {
    grid-column: 1;
    grid-row: 2;
}

/* Right lower left */
.home2-color-card:nth-child(5) {
    grid-column: 3;
    grid-row: 2;
    width: calc(50% - 12px);
}

/* Right lower middle */
.home2-color-card:nth-child(6) {
    grid-column: 3;
    grid-row: 2;
    margin-left: calc(50% + 12px);
    width: calc(50% - 12px);
}

/* Additional cards */
.home2-color-card:nth-child(7),
.home2-color-card:nth-child(8) {
    display: none;
}


/* =========================================================
   IMAGE OVERLAY
========================================================= */

.home2-color-overlay {
    position: absolute;
    inset: 0;

    background: linear-gradient(
        180deg,
        rgba(0, 0, 0, 0) 35%,
        rgba(0, 0, 0, 0.28) 100%
    );

    opacity: 0;

    transition: opacity 0.4s ease;

    pointer-events: none;
}


/* =========================================================
   PICK YOUR COLOR ACTION
========================================================= */

.home2-color-action {
    position: absolute;

    left: 50%;
    bottom: 25px;

    transform:
        translateX(-50%)
        translateY(15px);

    display: flex;
    flex-direction: column;
    align-items: center;

    opacity: 0;
    visibility: hidden;

    transition:
        opacity 0.4s ease,
        visibility 0.4s ease,
        transform 0.4s ease;

    z-index: 3;
}


/* =========================================================
   PICK YOUR COLOR LABEL
========================================================= */

.home2-color-action-title {
    position: relative;

    display: inline-flex;
    align-items: center;
    justify-content: center;

    min-width: 145px;
    min-height: 48px;

    padding: 0 18px;

    background: var(--color-orange);
    color: #ffffff;

    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 750;
    line-height: 1;
    text-align: center;

    white-space: nowrap;
}


/* Small pointer */

.home2-color-action-title::after {
    content: "";

    position: absolute;
    left: 50%;
    bottom: -8px;

    width: 16px;
    height: 16px;

    background: var(--color-orange);

    transform: translateX(-50%) rotate(45deg);
}


/* =========================================================
   COLOR SWATCHES
========================================================= */

.home2-color-swatches {
    display: flex;
    align-items: stretch;

    margin-top: 8px;

    border: 1px solid rgba(255, 255, 255, 0.75);
}

.home2-color-swatch {
    min-width: 105px;
    min-height: 56px;

    display: flex;
    align-items: center;
    justify-content: center;

    padding: 0 15px;

    background: var(--swatch-color);
    color: #ffffff;

    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 700;
    line-height: 1;

    text-align: center;

    text-shadow: 0 1px 3px rgba(0, 0, 0, 0.25);

    box-sizing: border-box;
}

.home2-color-swatch + .home2-color-swatch {
    border-left: 1px solid rgba(255, 255, 255, 0.65);
}


/* =========================================================
   HOVER
========================================================= */

.home2-color-card:hover .home2-color-image {
    transform: scale(1.06);
    filter: saturate(1.08);
}

.home2-color-card:hover .home2-color-overlay {
    opacity: 1;
}

.home2-color-card:hover .home2-color-action {
    opacity: 1;
    visibility: visible;

    transform:
        translateX(-50%)
        translateY(0);
}


/* =========================================================
   GALLERY FOOTER
========================================================= */

.home2-color-gallery-footer {
    width: 100%;
    margin-top: 48px;

    display: flex;
    align-items: center;
    justify-content: center;
    gap: 24px;

    text-align: center;
}

.home2-color-gallery-footer p {
    margin: 0;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 500;
    line-height: 1.5;
}


/* =========================================================
   CTA BUTTON
========================================================= */

.home2-color-gallery-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 10px;

    min-height: 48px;
    padding: 0 22px;

    border: 2px solid var(--color-orange);
    border-radius: 30px;

    background: var(--color-orange);
    color: #ffffff;

    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 700;
    line-height: 1;
    text-decoration: none;

    transition:
        background 0.3s ease,
        color 0.3s ease,
        transform 0.3s ease,
