}

.home2-color-gallery-button i {
    font-size: 13px;
    transition: transform 0.3s ease;
}

.home2-color-gallery-button:hover {
    background: transparent;
    color: var(--color-orange);

    transform: translateY(-3px);

    box-shadow:
        0 10px 25px rgba(255, 90, 54, 0.16);
}

.home2-color-gallery-button:hover i {
    transform: translateX(3px);
}


/* =========================================================
   DARK MODE
========================================================= */

body.dark-mode .home2-color-gallery-section {
    background: var(--color-bg);
}

body.dark-mode .home2-color-image-wrapper {
    background: var(--color-surface);
}

body.dark-mode .home2-color-gallery-button:hover {
    background: transparent;
    color: var(--color-orange);
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .home2-color-gallery-section {
    direction: rtl;
}

html[dir="rtl"] .home2-color-gallery {
    direction: rtl;
}

