/* =========================================================
   HOME 2
   SECTION 8: FAQ
   PART 2 - MAIN CSS
========================================================= */

.home2-faq-section {
    width: 100%;
    padding: 100px 0;
    background: var(--color-bg);
    overflow: hidden;
}

.home2-faq-container {
    width: 100%;
    max-width: 1550px;
    margin: 0 auto;
    padding: 0 30px;
    box-sizing: border-box;
}


/* =========================================================
   HEADER
========================================================= */

.home2-faq-header {
    width: 100%;
    max-width: 900px;
    margin: 0 auto 52px;
    text-align: center;
}

.home2-faq-eyebrow {
    display: block;
    margin: 0 0 14px;

    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 800;
    line-height: 1.4;
    letter-spacing: 3px;
    text-transform: uppercase;
}

.home2-faq-title {
    margin: 0;

    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 46px;
    font-weight: 800;
    line-height: 1.15;
    letter-spacing: -1.2px;
}

.home2-faq-title span {
    color: var(--color-orange);
}

.home2-faq-description {
    max-width: 720px;
    margin: 18px auto 0;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 16px;
    font-weight: 400;
    line-height: 1.7;
}


/* =========================================================
   FAQ TABS
========================================================= */

.home2-faq-tabs {
    width: 100%;
    max-width: 1050px;
    margin: 0 auto 45px;

    display: flex;
    align-items: center;
    justify-content: center;
    gap: 18px;

    flex-wrap: wrap;
}

.home2-faq-tab {
    min-width: 190px;
    min-height: 56px;

    padding: 0 26px;

    border: 2px solid var(--color-border);
    border-radius: 40px;

    background: var(--color-surface);
    color: var(--color-text);

    font-family: var(--font-family);
    font-size: 14px;
    font-weight: 700;
    line-height: 1;

    cursor: pointer;
    white-space: nowrap;

    transition:
        background 0.3s ease,
        color 0.3s ease,
        border-color 0.3s ease,
        transform 0.3s ease,
        box-shadow 0.3s ease;
}

.home2-faq-tab:hover {
    border-color: var(--color-orange);
    color: var(--color-orange);
    transform: translateY(-2px);
}

.home2-faq-tab.active {
    border-color: var(--color-orange);
    background: var(--color-orange);
    color: #ffffff;

    box-shadow:
        0 8px 20px rgba(255, 90, 54, 0.16);
}

.home2-faq-tab.active:hover {
    color: #ffffff;
    transform: translateY(-2px);
}


/* =========================================================
   FAQ LIST
========================================================= */

.home2-faq-list {
    width: 100%;
    max-width: 1350px;
    margin: 0 auto;

    display: flex;
    flex-direction: column;
    gap: 16px;
}


/* =========================================================
   FAQ ITEM
========================================================= */

.home2-faq-item {
    width: 100%;
    margin: 0;

    background: var(--color-surface);
    border: 1px solid var(--color-border);

    box-sizing: border-box;

    transition:
        border-color 0.3s ease,
        background 0.3s ease,
        box-shadow 0.3s ease;
}

.home2-faq-item.active {
    border-color: var(--color-orange);
    background: var(--color-orange);

    box-shadow:
        0 10px 30px rgba(255, 90, 54, 0.12);
}


/* =========================================================
   QUESTION
========================================================= */

.home2-faq-question {
    width: 100%;
    min-height: 78px;

    margin: 0;
    padding: 18px 28px;

    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 25px;

    border: 0;
    outline: none;

    background: transparent;
    color: var(--color-text);

    font-family: var(--font-family);
    font-size: 20px;
    font-weight: 700;
    line-height: 1.4;

    text-align: left;
    cursor: pointer;

    box-sizing: border-box;
}

.home2-faq-question > span:first-child {
    min-width: 0;
    flex: 1;
}

.home2-faq-item.active .home2-faq-question {
    color: #ffffff;
}


/* =========================================================
   FAQ ICON
========================================================= */

.home2-faq-icon {
    flex: 0 0 46px;

    width: 46px;
    height: 46px;

    display: flex;
    align-items: center;
    justify-content: center;

    border: 2px solid var(--color-text);
    border-radius: 50%;

    background: transparent;
    color: var(--color-text);

    box-sizing: border-box;

    transition:
        background 0.3s ease,
        color 0.3s ease,
        border-color 0.3s ease,
        transform 0.3s ease;
}

.home2-faq-icon i {
    font-size: 14px;
    line-height: 1;
}

.home2-faq-item.active .home2-faq-icon {
    border-color: #ffffff;
    background: #ffffff;
    color: var(--color-orange);
}


/* =========================================================
   ANSWER
========================================================= */

.home2-faq-answer {
    width: 100%;

    max-height: 0;
    overflow: hidden;

    padding: 0 28px;

    box-sizing: border-box;

    transition:
        max-height 0.4s ease,
        padding 0.4s ease;
}

.home2-faq-item.active .home2-faq-answer {
    max-height: 300px;
    padding: 0 28px 27px;
}

.home2-faq-answer p {
    max-width: 1120px;

    margin: 0;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 400;
    line-height: 1.75;
}

.home2-faq-item.active .home2-faq-answer p {
    color: rgba(255, 255, 255, 0.92);
}


/* =========================================================
   FAQ FOOTER
========================================================= */

.home2-faq-footer {
    width: 100%;
    margin: 45px auto 0;

    display: flex;
    align-items: center;
    justify-content: center;
    gap: 22px;

    text-align: center;
}

.home2-faq-footer p {
    margin: 0;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 500;
    line-height: 1.5;
}


/* =========================================================
   CONTACT BUTTON
========================================================= */

.home2-faq-contact-button {
    min-height: 48px;

    padding: 0 22px;

    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 10px;

    border: 2px solid var(--color-orange);
    border-radius: 30px;

    background: var(--color-orange);
    color: #ffffff;

    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 700;
    line-height: 1;

    text-decoration: none;

    transition:
        background 0.3s ease,
        color 0.3s ease,
        transform 0.3s ease,
        box-shadow 0.3s ease;
}

.home2-faq-contact-button i {
    font-size: 13px;

    transition: transform 0.3s ease;
}

.home2-faq-contact-button:hover {
    background: transparent;
    color: var(--color-orange);

    transform: translateY(-3px);

    box-shadow:
        0 10px 25px rgba(255, 90, 54, 0.15);
}

.home2-faq-contact-button:hover i {
    transform: translateX(3px);
}


/* =========================================================
   FOCUS
========================================================= */

.home2-faq-tab:focus-visible,
.home2-faq-question:focus-visible,
.home2-faq-contact-button:focus-visible {
    outline: 3px solid rgba(255, 90, 54, 0.3);
    outline-offset: 4px;
}


/* =========================================================
   DARK MODE
========================================================= */

body.dark-mode .home2-faq-section {
    background: var(--color-bg);
}

body.dark-mode .home2-faq-tab {
    background: var(--color-surface);
}

body.dark-mode .home2-faq-item {
    background: var(--color-surface);
}

body.dark-mode .home2-faq-item.active {
    background: var(--color-orange);
}

body.dark-mode .home2-faq-icon {
    border-color: var(--color-text);
    color: var(--color-text);
}

