    border-color: #ffffff;
    background: #ffffff;
    color: var(--color-orange);
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .home2-faq-section {
    direction: rtl;
}

html[dir="rtl"] .home2-faq-header,
html[dir="rtl"] .home2-faq-tabs,
html[dir="rtl"] .home2-faq-footer {
    direction: rtl;
}

html[dir="rtl"] .home2-faq-question {
    text-align: right;
}

html[dir="rtl"] .home2-faq-answer p {
    text-align: right;
}

html[dir="rtl"] .home2-faq-contact-button:hover i {
    transform: translateX(-3px);
}


/* =========================================================
   TOUCH DEVICES
========================================================= */

@media (hover: none) and (pointer: coarse) {

    .home2-faq-tab:hover {
        transform: none;
        box-shadow: none;
    }

    .home2-faq-contact-button:hover {
        transform: none;
        box-shadow: none;
    }

}


/* =========================================================
