/* =========================================================
   MAIN BANNER
========================================================= */

.home2-promo-banner {
    position: relative;

    width: 100%;
    min-height: 430px;

    display: flex;
    align-items: stretch;

    overflow: hidden;

    background: var(--color-orange);

