    width: 53%;

    padding: 50px 40px 50px 60px;

    display: flex;
    flex-direction: column;
    justify-content: center;

    box-sizing: border-box;
}

.home2-promo-eyebrow {
    display: inline-flex;
    align-items: center;

    width: fit-content;

    margin: 0 0 14px;

    color: rgba(255, 255, 255, 0.9);

    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 800;
    line-height: 1.4;
    letter-spacing: 2.5px;
    text-transform: uppercase;
}

.home2-promo-title {
    max-width: 560px;

    margin: 0;

    color: #ffffff;

    font-family: var(--font-family);
    font-size: 50px;
    font-weight: 800;
    line-height: 1.03;
    letter-spacing: -1.5px;
}

.home2-promo-title span {
    display: block;
    color: #ffffff;
}


/* =========================================================
   HIGHLIGHT PILL
========================================================= */

.home2-promo-highlight {
    width: fit-content;

    margin-top: 17px;
    padding: 6px 12px;

    border: 1px solid rgba(255, 255, 255, 0.75);
    border-radius: 30px;

    color: #ffffff;

    font-family: var(--font-family);
    font-size: 9px;
    font-weight: 800;
    line-height: 1.3;
    letter-spacing: 1.2px;

    box-sizing: border-box;
}


/* =========================================================
   OFFER
========================================================= */

.home2-promo-offer {
    margin-top: 18px;

    display: flex;
    align-items: center;
    gap: 12px;
}

.home2-promo-offer strong {
    color: #ffffff;

    font-family: var(--font-family);
    font-size: 52px;
    font-weight: 850;
    line-height: 0.9;
    letter-spacing: -2px;
}

.home2-promo-offer-text {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.home2-promo-offer-text span {
    color: #ffffff;

    font-family: var(--font-family);
    font-size: 18px;
    font-weight: 800;
    line-height: 1;
}

.home2-promo-offer-text small {
    color: rgba(255, 255, 255, 0.82);

    font-family: var(--font-family);
    font-size: 10px;
    font-weight: 500;
    line-height: 1.4;
}


/* =========================================================
   DESCRIPTION
========================================================= */

.home2-promo-description {
    max-width: 450px;

    margin: 14px 0 0;

    color: rgba(255, 255, 255, 0.86);

    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 400;
    line-height: 1.6;
}


/* =========================================================
   BUTTON
========================================================= */

.home2-promo-button {
    width: fit-content;
    min-height: 48px;

    margin-top: 20px;
    padding: 0 19px;

    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 11px;

    border: 2px solid #ffffff;
    border-radius: 4px;

    background: #ffffff;
    color: var(--color-orange);

    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 750;
    line-height: 1;
    text-decoration: none;

    box-sizing: border-box;

    transition:
        background 0.3s ease,
        color 0.3s ease,
        transform 0.3s ease,
        box-shadow 0.3s ease;
}

.home2-promo-button i {
    font-size: 11px;

    transition: transform 0.3s ease;
}

.home2-promo-button:hover {
    background: transparent;
    color: #ffffff;

    transform: translateY(-3px);

    box-shadow:
        0 10px 25px rgba(0, 0, 0, 0.12);
}

.home2-promo-button:hover i {
    transform: translateX(4px);
}


/* =========================================================
   RIGHT IMAGE
========================================================= */

.home2-promo-visual {
    position: absolute;

    top: 0;
    right: 0;

    width: 55%;
    height: 100%;

    overflow: hidden;

    box-sizing: border-box;
}

.home2-promo-image {
    display: block;

    width: 100%;
    height: 100%;

    object-fit: cover;

    transition: transform 0.7s ease;
}

.home2-promo-banner:hover .home2-promo-image {
    transform: scale(1.04);
}

.home2-promo-image-overlay {
    position: absolute;
    inset: 0;

    background:
        linear-gradient(
            90deg,
            rgba(255, 90, 54, 0.28),
            transparent 45%
        );

    pointer-events: none;
}


/* =========================================================
   DECORATIVE SHAPES
========================================================= */

.home2-promo-shape {
    position: absolute;

    z-index: 3;

    pointer-events: none;
}


/* Large curved orange/white transition */

.home2-promo-shape-top {
    top: -150px;
    right: 43%;

    width: 300px;
    height: 300px;

    border-radius: 50%;

    background: #ffffff;
}


/* Green accent replaced with light orange */

.home2-promo-shape-right {
    top: -90px;
    right: -70px;

    width: 220px;
    height: 220px;

    border-radius: 50%;

    background: var(--color-dark-orange);
}


/* Bottom white circle */

.home2-promo-shape-bottom {
    right: -65px;
    bottom: -135px;

    width: 250px;
    height: 250px;

    border-radius: 50%;

    background: #ffffff;
}


/* Small decorative circle */

.home2-promo-shape-circle {
    left: 47%;
    bottom: -70px;

    width: 140px;
    height: 140px;

    border-radius: 50%;

    background: rgba(255, 255, 255, 0.10);
}


/* =========================================================
   DARK MODE
========================================================= */

body.dark-mode .home2-promo-section {
    background: var(--color-bg);
}

body.dark-mode .home2-promo-shape-top,
body.dark-mode .home2-promo-shape-bottom {
    background: var(--color-surface);
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .home2-promo-section {
    direction: rtl;
}

html[dir="rtl"] .home2-promo-content {
    padding-left: 40px;
    padding-right: 60px;
}

html[dir="rtl"] .home2-promo-visual {
    right: auto;
    left: 0;
}

html[dir="rtl"] .home2-promo-image-overlay {
    background:
        linear-gradient(
            270deg,
            rgba(255, 90, 54, 0.28),
            transparent 45%
        );
}

html[dir="rtl"] .home2-promo-shape-top {
    right: auto;
    left: 43%;
}

html[dir="rtl"] .home2-promo-shape-right {
    right: auto;
    left: -70px;
}

html[dir="rtl"] .home2-promo-shape-bottom {
    right: auto;
    left: -65px;
}

html[dir="rtl"] .home2-promo-shape-circle {
    left: auto;
    right: 47%;
}

html[dir="rtl"] .home2-promo-button:hover i {
    transform: translateX(-4px);
}


/* =========================================================
   ACCESSIBILITY
========================================================= */

.home2-promo-button:focus-visible {
    outline: 3px solid rgba(255, 90, 54, 0.35);
    outline-offset: 4px;
}


/* =========================================================
   TOUCH
========================================================= */

@media (hover: none) and (pointer: coarse) {

    .home2-promo-banner:hover .home2-promo-image {
        transform: none;
    }

    .home2-promo-button:hover {
        transform: none;
        box-shadow: none;
    }

}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

