}


/* =========================================================
   CENTERED SECTION HEADER
========================================================= */

.h2-featured-work-header {
    width: 100%;
    max-width: 950px;

    margin: 0 auto 60px;

    display: flex;
    flex-direction: column;

    align-items: center;
    justify-content: center;

    gap: 22px;

    text-align: center;
}


.h2-featured-work-heading {
    width: 100%;

    display: flex;
    flex-direction: column;

    align-items: center;
}


/* =========================================================
   EYEBROW
========================================================= */

.h2-featured-work-eyebrow {
    display: block;

    margin: 0 0 14px;

    color: var(--color-orange);

    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 800;

    line-height: 1.4;
    letter-spacing: 2.5px;

    text-transform: uppercase;
}


/* =========================================================
   TITLE
========================================================= */

.h2-featured-work-title {
    max-width: 850px;

    margin: 0;

    color: var(--color-text);

    font-family: var(--font-family);
    font-size: 46px;
    font-weight: 800;

    line-height: 1.15;
    letter-spacing: -1.2px;

    text-align: center;
}


.h2-featured-work-title span {
    display: block;

    color: var(--color-orange);
}


/* =========================================================
   INTRO
========================================================= */

.h2-featured-work-intro {
    width: 100%;
    max-width: 850px;

    display: flex;
    flex-direction: column;

    align-items: center;

    gap: 22px;

    text-align: center;
}


.h2-featured-work-intro p {
    max-width: 780px;

    margin: 0;

    color: var(--color-text-muted);

    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 400;

    line-height: 1.75;

    text-align: center;
}


/* =========================================================
   MORE PROJECTS BUTTON
========================================================= */

.h2-featured-work-gallery-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;

    gap: 12px;

    padding: 0;

    color: var(--color-text);

    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 800;

    line-height: 1;
    letter-spacing: 1.2px;

    text-decoration: none;
    text-transform: uppercase;

    transition:
        color var(--transition-fast),
        transform var(--transition-fast);
}


.h2-featured-work-gallery-button:hover {
    color: var(--color-orange);

    transform: translateY(-2px);
}


.h2-featured-work-gallery-icon {
    width: 42px;
    height: 42px;

    flex: 0 0 42px;

    display: inline-flex;
    align-items: center;
    justify-content: center;

    border: 1px solid var(--color-orange);
    border-radius: 50%;

    color: var(--color-orange);

    transition:
        background var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast);
}


.h2-featured-work-gallery-icon i {
    font-size: 13px;

    transition:
        transform var(--transition-fast);
}


.h2-featured-work-gallery-button:hover
.h2-featured-work-gallery-icon {
    background: var(--color-orange);

    color: #ffffff;
}


.h2-featured-work-gallery-button:hover
.h2-featured-work-gallery-icon i {
    transform: translateX(2px);
}


/* =========================================================
   PROJECT GALLERY
========================================================= */

.h2-featured-work-gallery {
    width: 100%;
    max-width: 1500px;

    margin: 0 auto;

    display: grid;

    grid-template-columns:
        repeat(3, minmax(0, 1fr));

    gap: 24px;

    align-items: start;
}


/* =========================================================
   PROJECT CARD
========================================================= */

.h2-work-card {
    position: relative;

    min-width: 0;
    margin: 0;

    background: transparent;

    transition:
        transform 0.35s ease;
}


.h2-work-card:hover {
    transform: translateY(-6px);
}


/* =========================================================
   DESKTOP STAGGER
========================================================= */

.h2-work-card:nth-child(1) {
    margin-top: 0;
}

.h2-work-card:nth-child(2) {
    margin-top: 70px;
}

.h2-work-card:nth-child(3) {
    margin-top: 0;
}

.h2-work-card:nth-child(4) {
    margin-top: 45px;
}

.h2-work-card:nth-child(5) {
    margin-top: 0;
}

.h2-work-card:nth-child(6) {
    margin-top: 70px;
}


/* =========================================================
   CARD LINK
========================================================= */

.h2-work-card-link {
    display: block;

    color: inherit;

    text-decoration: none;
}


/* =========================================================
   IMAGE WRAPPER
========================================================= */

.h2-work-image-wrapper {
    position: relative;

    width: 100%;

    overflow: hidden;

    background: var(--color-bg);

    isolation: isolate;
}


.h2-work-card-tall
.h2-work-image-wrapper {
    height: 520px;
}


.h2-work-card-medium
.h2-work-image-wrapper {
    height: 410px;
}


/* =========================================================
   IMAGE
========================================================= */

.h2-work-image {
    display: block;

    width: 100%;
    height: 100%;

    object-fit: cover;

    transform: scale(1);

    transition:
        transform 0.7s cubic-bezier(.2,.7,.2,1);
}


.h2-work-card:hover
.h2-work-image {
    transform: scale(1.06);
}


/* =========================================================
   IMAGE OVERLAY
========================================================= */

.h2-work-image-overlay {
    position: absolute;

    inset: 0;

    z-index: 2;

    background: rgba(255, 90, 54, 0.76);

    opacity: 0;

    transition:
        opacity 0.4s ease;
}


.h2-work-card:hover
.h2-work-image-overlay {
    opacity: 1;
}


/* =========================================================
   VIEW CIRCLE
========================================================= */

.h2-work-view {
    position: absolute;

    top: 50%;
    left: 50%;

    z-index: 4;

    width: 92px;
    height: 92px;

    display: flex;
    align-items: center;
    justify-content: center;

    border: 1px solid rgba(255, 255, 255, 0.85);
    border-radius: 50%;

    background: rgba(255, 255, 255, 0.10);

    color: #ffffff;

    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 800;

    letter-spacing: 1.5px;

    transform:
        translate(-50%, -50%)
        scale(0.7);

    opacity: 0;

    transition:
        opacity 0.35s ease,
        transform 0.4s cubic-bezier(.2,.7,.2,1),
        background var(--transition-fast);
}


.h2-work-card:hover
.h2-work-view {
    opacity: 1;

    transform:
        translate(-50%, -50%)
        scale(1);
}


.h2-work-view:hover {
    background: #ffffff;
    color: var(--color-orange);
}


/* =========================================================
   PROJECT INFORMATION
========================================================= */

.h2-work-info {
    width: 100%;

    padding: 20px 2px 0;

    box-sizing: border-box;
}


.h2-work-info > span {
    display: block;

    margin: 0 0 8px;

    color: var(--color-orange);

    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 800;

    line-height: 1.4;
    letter-spacing: 1.6px;

    text-transform: uppercase;
}


.h2-work-info h3 {
    margin: 0;

    color: var(--color-text);

    font-family: var(--font-family);
    font-size: 21px;
    font-weight: 700;

    line-height: 1.35;
    letter-spacing: -0.2px;

    transition:
        color var(--transition-fast);
}


.h2-work-card:hover
.h2-work-info h3 {
    color: var(--color-orange);
}


/* =========================================================
   DARK MODE
========================================================= */

html.dark-mode
.h2-featured-work-section {
    background: var(--color-surface);
}


html.dark-mode
.h2-work-image-wrapper {
    background: var(--color-bg);
}


html.dark-mode
.h2-work-info h3 {
    color: var(--color-text);
}


html.dark-mode
.h2-featured-work-gallery-button {
    color: var(--color-text);
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"]
.h2-featured-work-header,
html[dir="rtl"]
.h2-featured-work-heading,
html[dir="rtl"]
.h2-featured-work-intro {
    direction: rtl;

    text-align: center;
}


html[dir="rtl"]
.h2-featured-work-gallery-button {
    direction: rtl;
}


html[dir="rtl"]
.h2-featured-work-gallery-icon i {
    transform: rotate(180deg);
}


html[dir="rtl"]
.h2-work-info {
    text-align: right;
}


/* =========================================================
   ACCESSIBILITY
========================================================= */

.h2-work-card-link:focus-visible,
.h2-featured-work-gallery-button:focus-visible {
    outline: 3px solid var(--color-orange);
    outline-offset: 5px;
}


/* =========================================================
   TOUCH DEVICES
========================================================= */

@media (hover: none) {

    .h2-work-card:hover {
        transform: none;
    }

    .h2-work-card:hover
    .h2-work-image {
        transform: none;
    }

    .h2-featured-work-gallery-button:hover {
        transform: none;
    }

}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .h2-work-card,
    .h2-work-image,
    .h2-work-image-overlay,
    .h2-work-view,
    .h2-work-info h3,
    .h2-featured-work-gallery-button,
    .h2-featured-work-gallery-icon,
    .h2-featured-work-gallery-icon i {
