/* =========================================================
   ABOUT US
   SECTION 6: OUR TEAM
   PART 2 — MAIN CSS
========================================================= */


/* =========================================================
   SECTION
========================================================= */

.about-team-section {
    width: 100%;
    padding: 100px 0;
    background: var(--color-bg);
    overflow: hidden;
}

.about-team-container {
    width: 100%;
    max-width: 1500px;
    margin: 0 auto;
    padding: 0 var(--container-padding);
    box-sizing: border-box;
}


/* =========================================================
   SECTION HEADER
========================================================= */

.about-team-header {
    max-width: 850px;
    margin: 0 auto;
    text-align: center;
}

.about-team-eyebrow {
    display: inline-block;
    margin-bottom: 15px;
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 800;
    line-height: 1.4;
    letter-spacing: 3px;
    text-transform: uppercase;
}

.about-team-title {
    margin: 0;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 46px;
    font-weight: 800;
    line-height: 1.15;
    letter-spacing: -1.2px;
}

.about-team-title span {
    color: var(--color-orange);
}

.about-team-intro {
    max-width: 700px;
    margin: 20px auto 0;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 400;
    line-height: 1.75;
}


/* =========================================================
   DIVIDER
========================================================= */

.about-team-divider {
    max-width: 760px;
    margin: 32px auto 48px;
    display: grid;
    grid-template-columns: 1fr auto 1fr;
    align-items: center;
    gap: 20px;
}

.about-team-divider span {
    height: 1px;
    background: var(--color-border);
}

.about-team-divider i {
    width: 44px;
    height: 44px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: var(--color-orange);
    color: #ffffff;
    font-size: 16px;
}


/* =========================================================
   TEAM GRID
========================================================= */

.about-team-grid {
    width: 100%;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 28px;
}


/* =========================================================
   TEAM CARD
========================================================= */

.about-team-card {
    min-width: 0;
    overflow: hidden;
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: 14px;
    box-shadow: 0 10px 28px rgba(0, 0, 0, 0.05);
    transition:
        transform var(--transition-fast),
        box-shadow var(--transition-fast),
        border-color var(--transition-fast);
}

.about-team-card:hover {
    transform: translateY(-7px);
    border-color: rgba(255, 90, 54, 0.30);
    box-shadow: 0 18px 40px rgba(0, 0, 0, 0.10);
}


/* =========================================================
   TEAM IMAGE
========================================================= */

.about-team-image-wrapper {
    position: relative;
    width: 100%;
    height: 410px;
    overflow: hidden;
    background: var(--color-bg);
}

.about-team-image {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
    transition: transform 0.6s ease;
}

.about-team-card:hover .about-team-image {
    transform: scale(1.05);
}


/* =========================================================
   IMAGE OVERLAY
========================================================= */

.about-team-image-overlay {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: flex-end;
    justify-content: center;
    padding: 24px;
    background: linear-gradient(
        180deg,
        transparent 55%,
        rgba(255, 90, 54, 0.82) 100%
    );
    opacity: 0;
    transition: opacity var(--transition-fast);
}

.about-team-card:hover .about-team-image-overlay {
    opacity: 1;
}


/* =========================================================
   SOCIAL ICONS — IMAGE HOVER
========================================================= */

.about-team-socials {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 9px;
    transform: translateY(12px);
    transition: transform var(--transition-fast);
}

.about-team-card:hover .about-team-socials {
    transform: translateY(0);
}

.about-team-socials a {
    width: 38px;
    height: 38px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: #ffffff;
    color: var(--color-orange);
    font-size: 14px;
    text-decoration: none;
    transition:
        background var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast);
}

.about-team-socials a:hover {
    background: var(--color-dark-orange);
    color: #ffffff;
    transform: translateY(-3px);
}


/* =========================================================
   TEAM INFORMATION
========================================================= */

.about-team-info {
    padding: 23px 18px 25px;
    text-align: center;
}

.about-team-name {
    margin: 0;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 20px;
    font-weight: 750;
    line-height: 1.3;
}

.about-team-role {
    display: block;
    margin-top: 7px;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 500;
    line-height: 1.5;
}


/* =========================================================
   MOBILE SOCIAL ICONS
========================================================= */

.about-team-mobile-socials {
    margin-top: 17px;
    display: none;
    align-items: center;
    justify-content: center;
    gap: 8px;
}

.about-team-mobile-socials a {
    width: 34px;
    height: 34px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: rgba(255, 90, 54, 0.10);
    color: var(--color-orange);
    font-size: 12px;
    text-decoration: none;
}


/* =========================================================
   VIEW ALL BUTTON
========================================================= */

.about-team-action {
    margin-top: 42px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.about-team-button {
    min-height: 50px;
    padding: 0 9px 0 24px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 14px;
    background: var(--color-orange);
    border: 2px solid var(--color-orange);
    border-radius: 50px;
    color: #ffffff;
    font-family: var(--font-family);
    font-size: var(--fs-button);
    font-weight: var(--fw-semibold);
    text-decoration: none;
    box-sizing: border-box;
    transition:
        background var(--transition-fast),
        border-color var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast);
}

.about-team-button i {
    width: 34px;
    height: 34px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: #ffffff;
    color: var(--color-orange);
    font-size: 12px;
    transition:
        background var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast);
}

.about-team-button:hover {
    background: var(--color-dark-orange);
    border-color: var(--color-dark-orange);
    transform: translateY(-2px);
}

.about-team-button:hover i {
    color: var(--color-dark-orange);
    transform: translateX(3px);
}


/* =========================================================
   DARK MODE
========================================================= */

html.dark-mode .about-team-section {
    background: var(--color-bg);
}

html.dark-mode .about-team-card {
    background: var(--color-surface);
}

html.dark-mode .about-team-card:hover {
    border-color: rgba(255, 90, 54, 0.40);
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .about-team-container {
    direction: rtl;
}

html[dir="rtl"] .about-team-header {
    text-align: center;
}

html[dir="rtl"] .about-team-button {
    direction: rtl;
}

html[dir="rtl"] .about-team-button:hover i {
    transform: translateX(-3px);
}


/* =========================================================
   ACCESSIBILITY
========================================================= */

.about-team-socials a:focus-visible,
.about-team-mobile-socials a:focus-visible,
.about-team-button:focus-visible {
    outline: 3px solid var(--color-orange);
    outline-offset: 3px;
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .about-team-card,
    .about-team-image,
    .about-team-image-overlay,
    .about-team-socials,
    .about-team-socials a,
    .about-team-button,
    .about-team-button i {
        transition: none;
    }
}


