/* =========================================================
   CONSULTATION PAGE
   SECTION 01: CONSULTATION HERO
   PART 2 - MAIN CSS
========================================================= */

.consultation-hero-section {
    position: relative;
    width: 100%;
    min-height: 680px;
    display: flex;
    align-items: center;
    overflow: hidden;
    isolation: isolate;
    background: var(--color-bg);
}

/* ---------------------------------------------------------
   BACKGROUND
--------------------------------------------------------- */

.consultation-hero-background {
    position: absolute;
    inset: 0;
    z-index: -3;
    overflow: hidden;
}

.consultation-hero-background-image {
    width: 100%;
    height: 100%;
    display: block;
    object-fit: cover;
    object-position: center;
    transition: transform 1.2s ease;
}

.consultation-hero-section:hover .consultation-hero-background-image {
    transform: scale(1.03);
}

/* ---------------------------------------------------------
   OVERLAY
--------------------------------------------------------- */

.consultation-hero-overlay {
    position: absolute;
    inset: 0;
    z-index: -2;
    background:
        linear-gradient(
            90deg,
            rgba(18, 18, 18, 0.88) 0%,
            rgba(18, 18, 18, 0.76) 38%,
            rgba(18, 18, 18, 0.42) 72%,
            rgba(18, 18, 18, 0.20) 100%
        );
}

/* ---------------------------------------------------------
   CONTAINER
--------------------------------------------------------- */

.consultation-hero-container {
    width: 100%;
    max-width: 1700px;
    min-height: 680px;
    margin: 0 auto;
    padding: 90px 30px;
    box-sizing: border-box;

    display: flex;
    align-items: center;
}

/* ---------------------------------------------------------
   CONTENT
--------------------------------------------------------- */

.consultation-hero-content {
    width: 100%;
    max-width: 900px;
    margin-left: 0;
}

.consultation-hero-eyebrow {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 12px;

    margin-bottom: 18px;

    color: #ffffff;
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 2.5px;
    line-height: 1.3;
}

.consultation-hero-eyebrow::before {
    content: "";
    width: 42px;
    height: 2px;
    flex: 0 0 42px;
    background: var(--color-orange);
}

/* ---------------------------------------------------------
   TITLE
--------------------------------------------------------- */

.consultation-hero-title {
    max-width: 850px;
    margin: 0 0 22px;

    color: #ffffff;
    font-family: var(--font-family);
    font-size: 58px;
    font-weight: 800;
    line-height: 1.08;
    letter-spacing: -1.5px;
}

.consultation-hero-title span {
    display: block;
    color: var(--color-orange);
}

/* ---------------------------------------------------------
   DESCRIPTION
--------------------------------------------------------- */

.consultation-hero-description {
    max-width: 700px;
    margin: 0 0 32px;

    color: rgba(255, 255, 255, 0.88);
    font-family: var(--font-family);
    font-size: 16px;
    font-weight: 400;
    line-height: 1.8;
}

/* ---------------------------------------------------------
   HIGHLIGHTS
--------------------------------------------------------- */

.consultation-hero-highlights {
    display: flex;
    align-items: stretch;
    flex-wrap: wrap;
    gap: 14px;
    margin-bottom: 34px;
}

.consultation-hero-highlight {
    min-width: 205px;
    display: flex;
    align-items: center;
    gap: 12px;

    padding: 12px 15px;

    box-sizing: border-box;
    background: rgba(255, 255, 255, 0.08);
    border: 1px solid rgba(255, 255, 255, 0.16);
    border-radius: 10px;

    backdrop-filter: blur(6px);
    -webkit-backdrop-filter: blur(6px);

    transition:
        transform var(--transition-fast),
        background var(--transition-fast),
        border-color var(--transition-fast);
}

.consultation-hero-highlight:hover {
    transform: translateY(-4px);
    background: rgba(255, 255, 255, 0.12);
    border-color: rgba(255, 90, 54, 0.45);
}

.consultation-hero-highlight-icon {
    flex: 0 0 42px;
    width: 42px;
    height: 42px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;
    background: rgba(255, 90, 54, 0.16);
    color: var(--color-orange);

    font-size: 16px;
}

.consultation-hero-highlight-content {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 3px;
}

.consultation-hero-highlight-content strong {
    color: #ffffff;
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 700;
    line-height: 1.3;
}

.consultation-hero-highlight-content span {
    color: rgba(255, 255, 255, 0.68);
    font-family: var(--font-family);
    font-size: 10px;
    font-weight: 400;
    line-height: 1.4;
}

/* ---------------------------------------------------------
   ACTIONS
--------------------------------------------------------- */

.consultation-hero-actions {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 14px;
}

.consultation-hero-primary-button,
.consultation-hero-secondary-button {
    min-height: 56px;
    box-sizing: border-box;

    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 12px;

    padding: 0 10px 0 22px;

    border-radius: 30px;
