/* =========================================================
   CONSULTATION PAGE
   SECTION 02: WHY CHOOSE A CONSULTATION
   PART 2 - MAIN CSS
========================================================= */

.consultation-why-section {
    position: relative;
    width: 100%;
    padding: 100px 0;
    overflow: hidden;
    background: var(--color-bg);
}

/* ---------------------------------------------------------
   CONTAINER
--------------------------------------------------------- */

.consultation-why-container {
    width: 100%;
    max-width: 1500px;
    margin: 0 auto;
    padding: 0 30px;
    box-sizing: border-box;

    display: grid;
    grid-template-columns: 0.95fr 1.05fr;
    align-items: center;
    gap: 80px;
}

/* ---------------------------------------------------------
   LEFT VISUAL
--------------------------------------------------------- */

.consultation-why-visual {
    position: relative;
    width: 100%;
    min-height: 560px;
}

.consultation-why-main-image-wrapper {
    position: relative;
    width: 100%;
    height: 560px;
    overflow: hidden;
    border-radius: 18px;
}

.consultation-why-main-image {
    width: 100%;
    height: 100%;
    display: block;
    object-fit: cover;
    object-position: center;
    transition: transform 0.8s ease;
}

.consultation-why-main-image-wrapper:hover
.consultation-why-main-image {
    transform: scale(1.04);
}

/* ---------------------------------------------------------
   CIRCULAR IMAGE
--------------------------------------------------------- */

.consultation-why-circle-image {
    position: absolute;
    left: 50%;
    bottom: -58px;
    transform: translateX(-50%);

    width: 190px;
    height: 190px;

    padding: 8px;
    box-sizing: border-box;

    border: 8px solid #ffffff;
    border-radius: 50%;
    overflow: hidden;

    background: var(--color-bg);
    box-shadow: 0 15px 35px rgba(0, 0, 0, 0.16);

    z-index: 3;
}

.consultation-why-circle-image-photo {
    width: 100%;
    height: 100%;
    display: block;
    object-fit: cover;
    border-radius: 50%;
}

/* ---------------------------------------------------------
   DECORATIVE DOTS
--------------------------------------------------------- */

.consultation-why-decoration {
    position: absolute;
    right: -28px;
    bottom: 5px;

    width: 105px;
    height: 105px;

    display: grid;
    grid-template-columns: repeat(3, 7px);
    grid-auto-rows: 7px;
    align-content: center;
    justify-content: center;
    gap: 9px;

    z-index: 1;
}

.consultation-why-decoration span {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: rgba(255, 90, 54, 0.20);
}

/* ---------------------------------------------------------
   RIGHT CONTENT
--------------------------------------------------------- */

.consultation-why-content {
    width: 100%;
    max-width: 680px;
}

.consultation-why-eyebrow {
    position: relative;
    display: inline-flex;
    align-items: center;

    margin-bottom: 18px;

    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 2px;
    line-height: 1.3;
}

.consultation-why-eyebrow::after {
    content: "";
    width: 70px;
    height: 2px;

    margin-left: 12px;

    background: var(--color-orange);
}

/* ---------------------------------------------------------
   TITLE
--------------------------------------------------------- */

.consultation-why-title {
    max-width: 650px;
    margin: 0 0 25px;

    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 48px;
    font-weight: 800;
    line-height: 1.12;
    letter-spacing: -1.2px;
}

.consultation-why-title span {
    display: block;
    color: var(--color-orange);
}

/* ---------------------------------------------------------
   DESCRIPTION
--------------------------------------------------------- */

.consultation-why-description {
    max-width: 650px;
    margin: 0 0 32px;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 400;
    line-height: 1.8;
}

/* ---------------------------------------------------------
   FEATURE ROW
--------------------------------------------------------- */

.consultation-why-feature-row {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 45px;

    margin-bottom: 30px;
}

.consultation-why-feature {
    display: flex;
    align-items: center;
    gap: 16px;
    min-width: 0;
}

.consultation-why-feature-icon {
    width: 76px;
    height: 76px;
    flex: 0 0 76px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: var(--color-orange);
    color: #ffffff;

    font-size: 27px;

    transition:
        transform var(--transition-fast),
        background var(--transition-fast),
        color var(--transition-fast);
}

.consultation-why-feature-icon-dark {
    background: var(--color-text);
    color: var(--color-orange);
}

.consultation-why-feature:hover .consultation-why-feature-icon {
    transform: translateY(-5px);
    background: var(--color-orange);
    color: #ffffff;
}

.consultation-why-feature-content {
    min-width: 0;
}

.consultation-why-feature-content h3 {
    margin: 0 0 7px;

    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 18px;
    font-weight: 700;
    line-height: 1.35;
}

.consultation-why-feature-content p {
    margin: 0;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 400;
    line-height: 1.55;
}

/* ---------------------------------------------------------
   SUPPORTING TEXT
--------------------------------------------------------- */

.consultation-why-supporting-text {
    max-width: 650px;
    margin: 0 0 30px;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 400;
    line-height: 1.8;
}

/* ---------------------------------------------------------
   ACTIONS
--------------------------------------------------------- */

.consultation-why-actions {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 25px;
}

.consultation-why-primary-button {
    min-width: 190px;
    min-height: 54px;

    display: inline-flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;

    padding: 0 8px 0 22px;
    box-sizing: border-box;

    border: 2px solid var(--color-orange);
    border-radius: 30px;

    background: var(--color-orange);
    color: #ffffff;

    font-family: var(--font-family);
    font-size: var(--fs-button);
    font-weight: var(--fw-semibold);
    line-height: 1;
    text-decoration: none;

    transition:
        background var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast),
        box-shadow var(--transition-fast);
}

.consultation-why-primary-button:hover {
    background: #ffffff;
    color: var(--color-orange);
    transform: translateY(-3px);
    box-shadow: 0 12px 28px rgba(0, 0, 0, 0.12);
}

.consultation-why-button-icon {
    width: 40px;
    height: 40px;
    flex: 0 0 40px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;
    background: #ffffff;
    color: var(--color-orange);

    font-size: 13px;

    transition:
        background var(--transition-fast),
        color var(--transition-fast);
}

.consultation-why-primary-button:hover
.consultation-why-button-icon {
    background: var(--color-orange);
    color: #ffffff;
}

/* ---------------------------------------------------------
   CHECK ITEM
--------------------------------------------------------- */

.consultation-why-check-item {
    display: inline-flex;
    align-items: center;
    gap: 10px;

    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 600;
}

.consultation-why-check-icon {
    width: 34px;
    height: 34px;
    flex: 0 0 34px;

    display: flex;
    align-items: center;
    justify-content: center;

    border: 1px solid rgba(255, 90, 54, 0.35);
    border-radius: 50%;

    background: rgba(255, 90, 54, 0.08);
    color: var(--color-orange);

    font-size: 12px;
}

/* ---------------------------------------------------------
   RTL
--------------------------------------------------------- */

html[dir="rtl"] .consultation-why-container {
    direction: rtl;
}

html[dir="rtl"] .consultation-why-content {
    text-align: right;
}

html[dir="rtl"] .consultation-why-eyebrow::after {
    margin-left: 0;
    margin-right: 12px;
}

html[dir="rtl"] .consultation-why-feature {
    flex-direction: row-reverse;
}

html[dir="rtl"] .consultation-why-actions {
    flex-direction: row-reverse;
}

html[dir="rtl"] .consultation-why-primary-button {
    padding-left: 8px;
    padding-right: 22px;
}

html[dir="rtl"] .consultation-why-button-icon {
    transform: rotate(180deg);
}

html[dir="rtl"] .consultation-why-decoration {
    right: auto;
    left: -28px;
}

/* ---------------------------------------------------------
   DARK MODE
--------------------------------------------------------- */

html.dark-mode .consultation-why-section {
    background: var(--color-bg);
}

html.dark-mode .consultation-why-circle-image {
    border-color: var(--color-surface);
    background: var(--color-surface);
}

html.dark-mode .consultation-why-feature-icon-dark {
    background: var(--color-surface);
    color: var(--color-orange);
}

html.dark-mode .consultation-why-primary-button:hover {
    background: var(--color-surface);
}

/* ---------------------------------------------------------
   FOCUS
--------------------------------------------------------- */

.consultation-why-primary-button:focus-visible {
    outline: 3px solid rgba(255, 90, 54, 0.35);
    outline-offset: 4px;
}

/* ---------------------------------------------------------
   TOUCH
--------------------------------------------------------- */

@media (hover: none) {

    .consultation-why-main-image-wrapper:hover
    .consultation-why-main-image {
        transform: none;
    }

    .consultation-why-feature:hover
    .consultation-why-feature-icon {
        transform: none;
    }

    .consultation-why-primary-button:hover {
        transform: none;
        box-shadow: none;
    }
}

/* ---------------------------------------------------------
   REDUCED MOTION
--------------------------------------------------------- */

@media (prefers-reduced-motion: reduce) {

    .consultation-why-main-image,
    .consultation-why-feature-icon,
    .consultation-why-primary-button,
    .consultation-why-button-icon {
        transition: none !important;
    }
}






