/* =========================================================
   CONSULTATION PAGE
   SECTION 06: POPULAR COLOUR COMBINATIONS
   PART 2 - MAIN CSS
========================================================= */

.consultation-popular-colours-section {
    position: relative;
    width: 100%;
    padding: 100px 0;
    overflow: hidden;
    background: var(--color-surface);
}


/* =========================================================
   CONTAINER
========================================================= */

.consultation-popular-colours-container {
    width: 100%;
    max-width: 1500px;
    margin: 0 auto;
    padding: 0 30px;
    box-sizing: border-box;
}


/* =========================================================
   SECTION HEADER
========================================================= */

.consultation-popular-colours-header {
    width: 100%;
    max-width: 850px;
    margin: 0 auto 60px;

    text-align: center;
}

.consultation-popular-colours-eyebrow {
    position: relative;

    display: inline-flex;
    align-items: center;
    justify-content: center;

    margin-bottom: 16px;

    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 2.5px;
    line-height: 1.3;
}

.consultation-popular-colours-eyebrow::before,
.consultation-popular-colours-eyebrow::after {
    content: "";

    width: 38px;
    height: 2px;

    background: var(--color-orange);
}

.consultation-popular-colours-eyebrow::before {
    margin-right: 12px;
}

.consultation-popular-colours-eyebrow::after {
    margin-left: 12px;
}

.consultation-popular-colours-title {
    margin: 0 0 18px;

    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 48px;
    font-weight: 800;
    line-height: 1.12;
    letter-spacing: -1px;
}

.consultation-popular-colours-title span {
    color: var(--color-orange);
}

.consultation-popular-colours-intro {
    max-width: 760px;
    margin: 0 auto;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 400;
    line-height: 1.8;
}

.consultation-popular-colours-divider {
    width: 280px;
    height: 42px;

    margin: 25px auto 0;

    display: flex;
    align-items: center;
    justify-content: center;
    gap: 14px;
}

.consultation-popular-colours-divider span {
    width: 90px;
    height: 1px;

    background: var(--color-border);
}

.consultation-popular-colours-divider i {
    width: 42px;
    height: 42px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: rgba(255, 90, 54, 0.10);
    color: var(--color-orange);

    font-size: 14px;
}


/* =========================================================
   COLOUR CARDS GRID
========================================================= */

.consultation-popular-colours-grid {
    width: 100%;

    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 30px;
}


/* =========================================================
   CARD
========================================================= */

.consultation-popular-colour-card {
    position: relative;

    min-width: 0;

    border: 1px solid var(--color-border);
    border-radius: 16px;

    background: var(--color-bg);

    overflow: hidden;

    transition:
        transform var(--transition-fast),
        box-shadow var(--transition-fast),
        border-color var(--transition-fast);
}

.consultation-popular-colour-card:hover {
    transform: translateY(-8px);

    border-color: rgba(255, 90, 54, 0.25);

    box-shadow:
        0 18px 38px rgba(0, 0, 0, 0.10);
}


/* =========================================================
   CARD LINK
========================================================= */

.consultation-popular-colour-link {
    display: block;

    color: inherit;
    text-decoration: none;
}


/* =========================================================
   IMAGE
========================================================= */

.consultation-popular-colour-image-wrapper {
    position: relative;

    width: 100%;
    height: 300px;

    overflow: hidden;
}

.consultation-popular-colour-image {
    width: 100%;
    height: 100%;

    display: block;

    object-fit: cover;
    object-position: center;

    transition: transform 0.8s ease;
}

.consultation-popular-colour-card:hover
.consultation-popular-colour-image {
    transform: scale(1.06);
}


/* =========================================================
   IMAGE OVERLAY
========================================================= */

.consultation-popular-colour-overlay {
    position: absolute;
    inset: 0;

    background:
        linear-gradient(
            180deg,
            rgba(0, 0, 0, 0.02) 35%,
            rgba(0, 0, 0, 0.42) 100%
        );

    pointer-events: none;
}


/* =========================================================
   CARD NUMBER
========================================================= */

.consultation-popular-colour-number {
    position: absolute;
    top: 18px;
    left: 18px;

    width: 42px;
    height: 42px;

    display: flex;
    align-items: center;
    justify-content: center;

    border: 2px solid #ffffff;
    border-radius: 50%;

    background: var(--color-orange);
    color: #ffffff;

    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 0.5px;

    box-shadow:
        0 6px 15px rgba(0, 0, 0, 0.15);

    z-index: 2;
}


/* =========================================================
   CARD ARROW
========================================================= */

.consultation-popular-colour-arrow {
    position: absolute;
    right: 18px;
    bottom: 18px;

    width: 42px;
    height: 42px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: #ffffff;
    color: var(--color-orange);

    font-size: 13px;

    z-index: 2;

    transition:
        background-color var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast);
}

.consultation-popular-colour-card:hover
.consultation-popular-colour-arrow {
    background: var(--color-orange);
    color: #ffffff;
    transform: translateX(4px);
}


/* =========================================================
   CARD CONTENT
========================================================= */

.consultation-popular-colour-content {
    min-height: 150px;

    padding: 22px 24px 24px;

    box-sizing: border-box;
}

.consultation-popular-colour-category {
    display: block;

    margin-bottom: 7px;

    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 1.5px;
    line-height: 1.3;
}

.consultation-popular-colour-content h3 {
    margin: 0 0 9px;

    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 21px;
    font-weight: 800;
    line-height: 1.3;
}

.consultation-popular-colour-content p {
    margin: 0;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 400;
    line-height: 1.6;
}


/* =========================================================
   BOTTOM CTA
========================================================= */

.consultation-popular-colours-bottom {
    width: 100%;

    margin-top: 45px;
    padding: 22px 25px;

    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 25px;

    box-sizing: border-box;

    border: 1px solid var(--color-border);
    border-radius: 14px;

    background: var(--color-bg);
}

.consultation-popular-colours-bottom-content {
    display: flex;
    align-items: center;
    gap: 14px;

    min-width: 0;
}

.consultation-popular-colours-bottom-icon {
    width: 46px;
    height: 46px;

    flex: 0 0 46px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: rgba(255, 90, 54, 0.10);
    color: var(--color-orange);

    font-size: 16px;
}

.consultation-popular-colours-bottom-content strong {
    display: block;

    margin-bottom: 4px;

    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 700;
    line-height: 1.3;
}

.consultation-popular-colours-bottom-content p {
    margin: 0;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 10px;
    font-weight: 400;
    line-height: 1.5;
}


/* =========================================================
   BOTTOM BUTTON
========================================================= */

.consultation-popular-colours-button {
    width: 195px;
    min-height: 52px;

    flex: 0 0 195px;

    display: inline-flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;

    padding: 0 8px 0 20px;

    box-sizing: border-box;

    border: 2px solid var(--color-orange);
    border-radius: 28px;

    background: var(--color-orange);
    color: #ffffff;

    font-family: var(--font-family);
    font-size: var(--fs-button);
    font-weight: var(--fw-semibold);
    line-height: 1;

    text-decoration: none;

    transition:
        background-color var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast),
        box-shadow var(--transition-fast);
}

.consultation-popular-colours-button:hover {
    background: var(--color-bg);
    color: var(--color-orange);

    transform: translateY(-3px);

    box-shadow:
        0 12px 28px rgba(0, 0, 0, 0.10);
}

.consultation-popular-colours-button-icon {
    width: 38px;
    height: 38px;

    flex: 0 0 38px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: #ffffff;
    color: var(--color-orange);

    font-size: 12px;

    transition:
        background-color var(--transition-fast),
        color var(--transition-fast);
}

.consultation-popular-colours-button:hover
.consultation-popular-colours-button-icon {
    background: var(--color-orange);
    color: #ffffff;
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .consultation-popular-colours-container {
    direction: rtl;
}

html[dir="rtl"] .consultation-popular-colours-eyebrow {
    flex-direction: row-reverse;
}

html[dir="rtl"] .consultation-popular-colours-eyebrow::before {
    margin-right: 0;
    margin-left: 12px;
}

html[dir="rtl"] .consultation-popular-colours-eyebrow::after {
    margin-left: 0;
    margin-right: 12px;
}

html[dir="rtl"] .consultation-popular-colour-card {
    text-align: right;
}

html[dir="rtl"] .consultation-popular-colour-number {
    left: auto;
    right: 18px;
}

html[dir="rtl"] .consultation-popular-colour-arrow {
    right: auto;
    left: 18px;
}

html[dir="rtl"] .consultation-popular-colour-card:hover
.consultation-popular-colour-arrow {
    transform: translateX(-4px);
}

html[dir="rtl"] .consultation-popular-colours-bottom {
    direction: rtl;
}

html[dir="rtl"] .consultation-popular-colours-bottom-content {
    flex-direction: row-reverse;
    text-align: right;
}

html[dir="rtl"] .consultation-popular-colours-button {
    padding-left: 8px;
    padding-right: 20px;
}

html[dir="rtl"] .consultation-popular-colours-button-icon {
    transform: rotate(180deg);
}


/* =========================================================
   DARK MODE
========================================================= */

html.dark-mode .consultation-popular-colour-card,
html.dark-mode .consultation-popular-colours-bottom {
    background: var(--color-bg);
}

html.dark-mode .consultation-popular-colours-button:hover {
    background: var(--color-surface);
}


/* =========================================================
   FOCUS
========================================================= */

.consultation-popular-colour-link:focus-visible,
.consultation-popular-colours-button:focus-visible {
    outline: 3px solid rgba(255, 90, 54, 0.30);
    outline-offset: 4px;
}


/* =========================================================
   TOUCH
========================================================= */

@media (hover: none) {

    .consultation-popular-colour-card:hover {
        transform: none;
        box-shadow: none;
    }

    .consultation-popular-colour-card:hover
    .consultation-popular-colour-image {
        transform: none;
    }

    .consultation-popular-colour-card:hover
    .consultation-popular-colour-arrow {
        transform: none;
        background: #ffffff;
        color: var(--color-orange);
    }

    .consultation-popular-colours-button:hover {
        transform: none;
        box-shadow: none;
    }
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .consultation-popular-colour-card,
    .consultation-popular-colour-image,
    .consultation-popular-colour-arrow,
    .consultation-popular-colours-button,
    .consultation-popular-colours-button-icon {
        transition: none !important;
    }
}






