/* =========================================================
   CONTACT PAGE
   SECTION 02: CONTACT INFORMATION
   PART 2 - MAIN CSS
   CONSISTENT TYPOGRAPHY
========================================================= */

.contact-information-section {
    width: 100%;
    padding: 100px 0;
    background: var(--color-surface);
    overflow: hidden;
}

.contact-information-container {
    width: 100%;
    max-width: 1500px;
    margin: 0 auto;
    padding: 0 30px;
    box-sizing: border-box;
}


/* =========================================================
   SECTION HEADER
========================================================= */

.contact-information-header {
    width: 100%;
    max-width: 850px;
    margin: 0 auto 60px;
    text-align: center;
}

.contact-information-eyebrow {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    margin-bottom: 15px;
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 2.5px;
    line-height: 1.3;
}

.contact-information-eyebrow::before,
.contact-information-eyebrow::after {
    content: "";
    width: 38px;
    height: 2px;
    background: var(--color-orange);
    display: inline-block;
}

.contact-information-title {
    margin: 0 0 17px;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 48px;
    font-weight: 800;
    line-height: 1.15;
    letter-spacing: -0.8px;
}

.contact-information-title span {
    color: var(--color-orange);
}

.contact-information-intro {
    max-width: 700px;
    margin: 0 auto;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 400;
    line-height: 1.8;
}

.contact-information-divider {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    width: 280px;
    margin: 25px auto 0;
}

.contact-information-divider span {
    flex: 1;
    height: 1px;
    background: var(--color-border);
}

.contact-information-divider i {
    width: 42px;
    height: 42px;
    flex: 0 0 42px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: rgba(255, 90, 54, 0.10);
    color: var(--color-orange);
    font-size: 15px;
}


/* =========================================================
   CONTACT GRID
========================================================= */

.contact-information-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 24px;
}


/* =========================================================
   CARD
========================================================= */

.contact-information-card {
    position: relative;
    min-width: 0;
    min-height: 300px;
    padding: 28px 25px 30px;
    box-sizing: border-box;
    background: var(--color-bg);
    border: 1px solid var(--color-border);
    border-radius: 16px;
    overflow: hidden;
    transition:
        transform var(--transition-fast),
        box-shadow var(--transition-fast),
        border-color var(--transition-fast);
}

.contact-information-card::after {
    content: "";
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    height: 3px;
    background: var(--color-orange);
    transform: scaleX(0);
    transform-origin: center;
    transition: transform var(--transition-fast);
}

.contact-information-card:hover {
    transform: translateY(-7px);
    border-color: rgba(255, 90, 54, 0.30);
    box-shadow: 0 15px 35px rgba(0, 0, 0, 0.09);
}

.contact-information-card:hover::after {
    transform: scaleX(1);
}


/* =========================================================
   CARD TOP
========================================================= */

.contact-information-card-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 25px;
}

.contact-information-icon {
    width: 58px;
    height: 58px;
    flex: 0 0 58px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: rgba(255, 90, 54, 0.10);
    color: var(--color-orange);
    transition:
        background var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast);
}

.contact-information-icon i {
    font-size: 18px;
}

.contact-information-number {
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 1px;
}


/* =========================================================
   CARD CONTENT
========================================================= */

.contact-information-card-content h3 {
    margin: 0 0 10px;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 21px;
    font-weight: 800;
    line-height: 1.3;
}

.contact-information-card-content p {
    margin: 0 0 18px;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 400;
    line-height: 1.75;
}


/* =========================================================
   CONTACT LINK
========================================================= */

.contact-information-link {
    display: inline-flex;
    align-items: center;
    gap: 9px;
    max-width: 100%;
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 800;
    line-height: 1.4;
    text-decoration: none;
    overflow-wrap: anywhere;
    transition:
        color var(--transition-fast),
        gap var(--transition-fast);
}

.contact-information-link i {
    font-size: 10px;
}

.contact-information-link:hover {
    color: var(--color-dark-orange);
    gap: 13px;
}


/* =========================================================
   WORKING HOURS
========================================================= */

.contact-information-hours {
    display: flex;
    flex-direction: column;
    gap: 9px;
    margin-top: 2px;
}

.contact-information-hours div {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.contact-information-hours span {
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 9px;
    font-weight: 500;
    line-height: 1.4;
}

.contact-information-hours strong {
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 10px;
    font-weight: 700;
    line-height: 1.4;
}


/* =========================================================
   BOTTOM NOTE
========================================================= */

.contact-information-bottom {
    max-width: 1050px;
    min-height: 70px;
    margin: 45px auto 0;
    padding: 12px 25px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 13px;
    box-sizing: border-box;
    border: 1px solid var(--color-border);
    border-radius: 12px;
    background: var(--color-bg);
}

.contact-information-bottom-icon {
    width: 44px;
    height: 44px;
    flex: 0 0 44px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: rgba(255, 90, 54, 0.10);
    color: var(--color-orange);
}

.contact-information-bottom-icon i {
    font-size: 15px;
}

.contact-information-bottom p {
    margin: 0;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 500;
    line-height: 1.5;
}

.contact-information-bottom strong {
    color: var(--color-orange);
    font-weight: 800;
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .contact-information-container {
    direction: rtl;
}

html[dir="rtl"] .contact-information-card {
    text-align: right;
}

html[dir="rtl"] .contact-information-link {
    flex-direction: row-reverse;
}

html[dir="rtl"] .contact-information-bottom {
    direction: rtl;
}


/* =========================================================
   DARK MODE
========================================================= */

html.dark-mode .contact-information-card:hover {
    box-shadow: 0 15px 35px rgba(0, 0, 0, 0.25);
}

html.dark-mode .contact-information-bottom {
    background: var(--color-bg);
}


/* =========================================================
   FOCUS
========================================================= */

.contact-information-link:focus-visible {
    outline: 3px solid rgba(255, 90, 54, 0.25);
    outline-offset: 4px;
}


/* =========================================================
   TOUCH
========================================================= */

@media (hover: none) {

    .contact-information-card:hover {
        transform: none;
        box-shadow: none;
        border-color: var(--color-border);
    }

    .contact-information-card:hover::after {
        transform: scaleX(0);
    }

    .contact-information-link:hover {
        gap: 9px;
    }
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .contact-information-card,
    .contact-information-card::after,
    .contact-information-icon,
    .contact-information-link {
        transition: none;
    }
}



